(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0019.js"] = [{"id":"poem-7c57bb0cd0dcf1df1a132642","title":"采桑子·何人解赏西湖好","author":"欧阳修","dynasty":"宋","verses":["何人解赏西湖好，佳景无时。","飞盖相追。","贪向花间醉玉卮。","谁知闲凭阑干处，芳草斜晖。","水远烟微。","一点沧洲白鹭飞。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-602","tags":["西湖"]},{"id":"poem-7c585b5af87f7d5ee0f2a819","title":"夏日奉陪陆使君长源公堂集","author":"皎然","dynasty":"唐","verses":["府中自清远，六月高梧间。","寥亮泛雅瑟，逍遥扣玄关。","岭云与人静，庭鹤随公闲。","动息谅兼遂，兹情即东山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-eced748b-2e7b-4991-82e4-5898eb8e8e77","tags":[]},{"id":"poem-7c59bd957cbbbbf7d805642a","title":"清平乐·添烟深漾","author":"纳兰性德","dynasty":"清","verses":["麝烟深漾。","人拥缑笙氅。","新恨暗随新月长。","不辨眉尖心上。","六花斜扑疏帘。","地衣红锦轻沾。","记取暖香如梦，耐他一晌寒岩。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-163","tags":[]},{"id":"poem-7c5d406f2d275f40ea73e803","title":"双双燕·小桃谢后","author":"吴文英","dynasty":"宋","verses":["小桃谢后，双双燕，飞来几家庭户。","轻烟晓暝，湘水暮云遥度。","帘外馀寒未卷，共斜入、红楼深处。","相将占得雕梁，似约韶光留住。","堪举。","翩翩翠羽。","杨柳岸，泥香半和梅雨。","落花风软，戏促乱红飞舞。","多少呢喃意绪。","尽日向、流莺分诉。","还过短墙，谁会万千言语。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-503","tags":[]},{"id":"poem-7c5d80e2edf5e1319cfe318c","title":"尾声","author":"施惠《幽闺记》","dynasty":"元","verses":["(小旦)衷心先自不如意，纵然间旨同随喜，也做了兴尽空回。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3060","tags":[]},{"id":"poem-7c5fb190d05f58aa4a147240","title":"次韵成季尚书宁川即事五首 山寺寓居","author":"綦崇礼","dynasty":"宋","verses":["宣室思前席，承明虚直庐。","不肯入州府，分其终隐欤。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-e4276716-57e9-4d15-9929-4ff1dc675f03","tags":[]},{"id":"poem-7c6151e6ba34a4445e4aa651","title":"顶山栗","author":"王伯广","dynasty":"宋","verses":["黄篱抱中实，紫苞发外彩。","寄踪蜂窠垂，藏头猬皮隘。","讵堪鼯鼠窃，更复猿猱采。","心怜使民畏，时须徇儿爱。","荆山破金璞，骊珠掩微颣。","缜密文自保，滋味身乃碎。","筠笼贡厥珍，不在柤梨外。","罗笾加其仪，顾与菱芡对。","易饱屏膏肉，余功益肝肺。","悬风当令坚，致湿忍使败。","晋地枣非偶，宣城蜜佳配。","谁知麝香囊，可居天下最。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-a708bbb0-f1cc-42f7-a65d-366a4c00e23d","tags":[]},{"id":"poem-7c667bb8e118d855aeaa20ad","title":"相逢歌赠严二别驾","author":"杜甫","dynasty":"唐","verses":["我行入东川，十步一回首。","城都乱罢气萧飒，浣花草堂亦何有。","梓中豪俊大者谁，本州从事知名久。","把臂开尊饮我酒，酒酣击劒蛟龙吼。","乌帽拂尘青螺粟，紫衣将炙绯衣走。","铜盘烧蜡光吐日，夜如何其初促膝。","黄昏始扣主人门，谁谓俄顷胶在漆。","万事尽付形骸外，百年未见欢娱毕。","神倾意豁真佳士，久客多忧今愈疾。","高视乾坤又可愁，一躯交态同悠悠。","垂老遇君未恨晚，似君须向古人求。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-97c77587-617f-4389-b566-98d7279a8669","tags":[]},{"id":"poem-7c81c7bb4bbd23eeb2ba06ba","title":"旅舍对雪赠考功王员外","author":"李端","dynasty":"唐","verses":["杨花惊满路，面市忽狂风。","骤下摇兰叶，轻飞集竹丛。","欲将琼树比，不共玉人同。","独望徽之棹，青山在雪中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-5fbdbf12-a0c7-4e46-bca8-8d09a3dfdaa8","tags":[]},{"id":"poem-7c81f00b2817e40457d5c72f","title":"匪风","author":"佚名","dynasty":"先秦","verses":["匪风发兮，匪车偈兮。顾瞻周道，中心怛兮。","匪风飘兮，匪车嘌兮。顾瞻周道，中心吊兮。","谁能亨鱼？溉之釜鬵。谁将西归？怀之好音。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-148","tags":[]},{"id":"poem-7c8370604e012c94c3a277fe","title":"兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十二","author":"易静","dynasty":"唐","verses":["何煞重，天狗是其殃。","无杀福神相次恶，天雷并者是（京本作「也」）无妨，三杀可商量（京本作「参商」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-0bfe5e0f-202a-4643-9f1c-eb05197ef4df","tags":[]},{"id":"poem-7c8ae7c35100474cea00bc53","title":"又和内院海棠","author":"苏颂","dynasty":"宋","verses":["华萼相辉采翠重，几番浓艳九春中。","根盘省闼偏含润，影拂邻墙暗逐风。","繁若百枝然宝炷，深于三入染𫄸红。","诸君赏咏时连属，珍重多才好事同。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-fed43d29-8bc2-4b2f-b647-76a09d1b4469","tags":[]},{"id":"poem-7c8b48961eeb7d1da22c0ca3","title":"越中送王使君赴江华","author":"崔峒","dynasty":"唐","verses":["皂盖春风自越溪，独寻芳树桂阳西。","远水浮云随马去，空山弱筿向云低。","遥知异政荆门北，旧许新诗康乐齐。","万里相思在何处，九疑残雪白猿啼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-1945ec6b-ad53-4e03-8cd8-24f84d51add5","tags":[]},{"id":"poem-7c9092857c8ce257c8a7996b","title":"菩萨蛮·春云吹散湘帘雨","author":"纳兰性德","dynasty":"清","verses":["春云吹散湘帘雨，絮黏蝴蝶飞还住。","人在玉楼中，楼高四面风。","柳烟丝一把，暝色笼鸳瓦。","休近小阑干，夕阳无限山。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-155","tags":[]},{"id":"poem-7c9b71138504e44c15e85037","title":"荅李侍御问","author":"皎然","dynasty":"唐","verses":["入道曾经离乱前，长干古寺住多年。","爱贫唯制莲花足，取性闲书树叶篇。","自笑不归看石牓，谁高无事弄苔泉。","身外空名何足问，吾心已出第三禅。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-9a07e5e5-a579-4693-abdd-cafb3ed67bfa","tags":[]},{"id":"poem-7c9cf9068f99ad4dee8fce83","title":"依韵修睦上人山居十首 三","author":"李咸用","dynasty":"唐","verses":["莫言天道终难定，须信人心尽自轻。","宣室三千虽有恨，成周八百岂无情。","栢缘执性长时瘦，梅为多知两番生。","不是不同明主意，嬾将唇舌与齐烹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-479b6c5c-d1f0-4d28-a6f6-772e1c275ea7","tags":[]},{"id":"poem-7c9fc5cd9254d2c106e5ad75","title":"无题二首 一","author":"李商隐","dynasty":"唐","verses":["凤尾香罗薄几重，碧文圆顶夜深缝。","扇裁月魄羞难掩，车走雷声语未通。","曾是寂寥金烬暗，断无消息石榴红。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-e006dfd3-40be-40ef-ba3b-552428931ae3","tags":["思念","七言律诗","唐诗三百首"]},{"id":"poem-7ca259d78ccc049383ff53d1","title":"酌","author":"佚名","dynasty":"先秦","verses":["于铄王师，遵养时晦。时纯熙矣，是用大介。我龙受之，𫏋𫏋王之造。载用有嗣，实维尔公允师。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-292","tags":[]},{"id":"poem-7ca62ce61e38d5a036305790","title":"送刘方石归旴江  其二","author":"王同祖","dynasty":"宋","verses":["昨日新闻未忍听，忧时赢得鬓毛星。","归休高卧西江上，祗恐川原草木腥。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-9adcea7c-d08d-49da-a128-07efea296e20","tags":[]},{"id":"poem-7cb0155ad10776cc53188687","title":"句","author":"戴寥","dynasty":"唐","verses":["蛾遶灯轮千燄动，鹤飞云路一声长。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-f0f20252-f630-416e-8870-fb925fbae481","tags":[]},{"id":"poem-7cb1c881288969430508b6b8","title":"调笑令·双绿","author":"李邴","dynasty":"宋","verses":["双绿。","淡匀拂。","两脸春融光透玉。","起来却怕东风触。","本是一团香玉。","飞鸾台上看未足。","贮向阿娇金屋。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-995","tags":[]},{"id":"poem-7cb28d7e7aadd29e9b0ab627","title":"酒泉子·楚女不归","author":"温庭筠","dynasty":"唐","verses":["楚女不归，楼枕小河春水。","月孤明，风又起，杏花稀。","玉钗斜簪云鬟髻，裙上金缕凤。","八行书，千里梦，雁南归。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-24","tags":[]},{"id":"poem-7cb2b6d68591d5a4667ccef9","title":"难忘曲","author":"李贺","dynasty":"唐","verses":["夹道开洞门，弱杨低画戟。","帘影竹华起，箫声吹日色。","蜂语绕妆镜，拂蛾学春碧。","乱系丁香梢，满栏花向夕。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-55b00fa6-b2d9-48a4-8fdb-54306ce1f937","tags":[]},{"id":"poem-7cb5c50a7e335ee2bbc844a6","title":"精列","author":"曹操","dynasty":"汉","verses":["厥初生，造划之陶物，莫不有终期。","莫不有终期。","圣贤不能免，何为怀此忧？","愿螭龙之驾，思想昆仑居。","思想昆仑居。","见期于迂怪，志意在蓬莱。","志意在蓬莱。","周礼圣徂落，会稽以坟丘。","会稽以坟丘。","陶陶谁能度？君子以弗忧。","年之暮奈何，时过时来微。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-7","tags":[]},{"id":"poem-7cb853abd607611eff97c63e","title":"访道士","author":"裴说","dynasty":"唐","verses":["高冈微雨后，木脱草堂新。","惟有疎慵者，来看淡薄人。","竹牙生碍路，松子落敲巾。","麤得玄中趣，当期宿话频。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-ce876e0a-68ac-4ffe-b735-02546c4639a8","tags":[]},{"id":"poem-7cbd202dcc70de553bb919cc","title":"谢侯彦明惠白莲栽  其二","author":"张栻","dynasty":"宋","verses":["青鞋不踏远公社，偶共濂溪嗜好同。","少待薰风开玉镜，与君来赋月明中。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-3b1ec935-e154-4bc1-be6a-6078686e4d3f","tags":[]},{"id":"poem-7cc7c048a114357a193b3675","title":"喜雨美王长官","author":"释居简","dynasty":"宋","verses":["四月五月河港枯，下田上田龟拆涂。","山湫剑沕龙光閟，一呼便为苍生超。","油然请命朝帝阍，触翻玉女洗头盆。","女从帝傍辄大笑，紫金蛇掣暾重昏。","田穉九死皆返魂，舳舻衔尾沙水浑。","扣如虚谷有逸响，享以明德无繁文。","去年老瓦鸡豚酒，酒酣说尹终在口。","属闻今复办多多，更听醉农新咏歌。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-3c597a3a-8eca-43a1-a46b-dfa524fcb677","tags":[]},{"id":"poem-7cddb23df9ca3374765f4872","title":"点绛唇·一种蛾眉","author":"纳兰性德","dynasty":"清","verses":["一种蛾眉，下弦不似初弦好。","庾郎未老，何事伤心早。","素壁斜辉，竹影横窗扫。","空房悄，乌啼欲晓，又下西楼了。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-15","tags":[]},{"id":"poem-7ce790595dae973ef05a504a","title":"中兴乐·池塘暖碧浸晴晖","author":"牛希济","dynasty":"五代","verses":["池塘暖碧浸晴晖，蒙蒙柳絮轻飞。","红蕊凋来，解梦还稀。","春云空有雁归，珠帘垂。","东风寂寞，恨郎抛掷，泪湿罗衣。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-42","tags":[]},{"id":"poem-7ce9da0ef397c03682eb735d","title":"兵要望江南 《周易》占候第二十六（三十七首） 三十","author":"易静","dynasty":"唐","verses":["外卦静，内动见兄爻。","空亡临象虚惊事，更兼不定事无毫，固守且平交。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-7d4ab225-21bd-45df-946b-afc513a75078","tags":[]},{"id":"poem-7cf4f6ed894bbfe2c6aac501","title":"寄清越上人","author":"张乔","dynasty":"唐","verses":["大道本来无所染，白云那得有心期。","远公独刻莲花漏，犹向空山礼六时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-72561e12-6f17-4f35-96cb-fc591e621567","tags":[]},{"id":"poem-7cf911eb6010299f552278d1","title":"客至","author":"赵嘏","dynasty":"唐","verses":["得路逢津更俊才，可怜鞍马照春来。","残花几日小斋闭，大笑一声幽抱开。","袖拂碧溪寒缭绕，冠欹红树晚裴回。","相逢少别更堪恨，何必秋风江上台。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-adb27b34-0f01-48b7-a406-4b743715970a","tags":[]},{"id":"poem-7d0ce1e34b3ea71d1a3f9a96","title":"酒泉子·谢却荼蘼","author":"纳兰性德","dynasty":"清","verses":["谢却荼蘼，一片月明如水。","篆香消，犹未睡，早鸦啼。","嫩寒无赖罗衣薄，休傍阑干角。","最愁人，灯欲落，雁还飞。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-5","tags":[]},{"id":"poem-7d14586b52bc24cbe4805113","title":"召旻","author":"佚名","dynasty":"先秦","verses":["旻天疾威，天笃降丧。瘨我饥馑，民卒流亡。我居圉卒荒。","天降罪罟，蟊贼内讧。昏椓靡共，溃溃回遹，实靖夷我邦。","皋皋訿訿，曾不知其玷。兢兢业业，孔填不宁，我位孔贬。","如彼岁旱，草不溃茂，如彼栖苴。我相此邦，无不溃止。","维昔之富不如时，维今之疚不如兹。彼疏斯粺，胡不自替？职兄斯引。","池之竭矣，不云自频。泉之竭矣，不云自中。溥斯害矣，职兄斯弘，不灾我躬。","昔先王受命，有如召公，日辟国百里，今也日蹙国百里。于乎哀哉！维今之人，不尚有旧！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-264","tags":[]},{"id":"poem-7d1ecb5f725be2e402aa0405","title":"虞美人·曲阑深处重相见","author":"纳兰性德","dynasty":"清","verses":["曲阑深处重相见，匀泪偎人颤。","凄凉别后两应同，最是不胜清怨月明中。","半生已分孤眠过，山枕檀痕涴。","忆来何事最销魂，第一折枝花样画罗裙。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-191","tags":[]},{"id":"poem-7d21a7ed15321507e3b14ee2","title":"游长宁公主流杯池二十五首 十","author":"上官昭容","dynasty":"唐","verses":["霁晓气清和，披襟赏薜萝。","玳瑁凝春色，琉璃漾水波。","跂石聊长啸，攀松乍短歌。","除非物外者，谁就此经过。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-050572f1-02f6-40f3-8318-dbe7f8353a84","tags":[]},{"id":"poem-7d23195bd772f1c2aa78c467","title":"题麟凤碑","author":"米芾","dynasty":"宋","verses":["非篆非科璞已雕，形容振振与萧萧。","曾因忠厚方周德，坐想𬣙谟览舜韶。","汉德已衰还应孽，鲁邦既弱不为妖。","虚斋自是惊人玩，不胜雄狐逐怒雕。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-8a21051c-de4f-4db3-81d2-ed601c525cdf","tags":[]},{"id":"poem-7d246c7e178cf8ee4a662914","title":"初春登楼即目观作述怀","author":"太宗皇帝","dynasty":"唐","verses":["凭轩俯兰阁，眺瞩散灵襟。","绮峰含翠雾，照日蕊红林。","镂丹霞锦岫，残素雪斑岑。","拂浪堤垂柳，娇花鸟续吟。","连甍岂一拱，众干如千寻。","明非独材力，终藉栋梁深。","弥怀矜乐志，更惧戒盈心。","媿制劳居逸，方规十产金。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-fd63be75-f6b3-491d-91d5-04179194f1aa","tags":[]},{"id":"poem-7d249e54a12b585e72b4d81a","title":"虞美人·粉娥齐敛千金笑","author":"贺铸","dynasty":"宋","verses":["粉娥齐敛千金笑。","愁结眉峰小。","渭城才唱浥轻尘。","无奈两行红泪、湿香巾。","伤心风月南城道。","几纵朱轓到。","明年载酒洛阳春。","还念淮山楼上、倚阑人。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-9","tags":[]},{"id":"poem-7d27b111bd8ba37873d7d233","title":"金銮坡上南望","author":"郑畋","dynasty":"唐","verses":["玉晨钟韵上清虚，画戟祥烟拱帝居。","极眼向南无限地，绿烟深处认中书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-52854c29-5ef8-45bd-9044-9966bcaad0a3","tags":[]},{"id":"poem-7d28939cfbaab2cd96993480","title":"朗月行","author":"张渐","dynasty":"唐","verses":["朗月照帘幌，清夜有余姿。","洞房怨孤枕，挟琴爱前墀。","萱草已数叶，梨花复徧枝。","去岁草始荣，与君新相知。","今年花未落，谁分生别离。","代情难重论，人事好乖移。","合比月华满，分同月易亏。","亏月当再圆，人别星陨天。","吾欲竟此曲，意深不可传。","叹息孤鸾鸟，伤心明镜前。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-2840b0a9-5b1c-462e-8069-c5b5d5a96dbf","tags":[]},{"id":"poem-7d2e6ab3b6bcc3e22d426bb7","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["你夺将去，真可怜，公婆望奴奴不见。","纵然他不埋怨，道我做媳妇还何干？他忍饥，添我夫罪愆。","怎得见，我夫面？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5044","tags":[]},{"id":"poem-7d3dcf4bb5e51523acc441e0","title":"八拍蛮·愁锁黛眉烟易惨","author":"阎选","dynasty":"五代","verses":["愁锁黛眉烟易惨，泪飘红脸粉难匀。","憔悴不知缘底事，遇人推道不宜春。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-25","tags":[]},{"id":"poem-7d466b8df20ebd135e2f52a7","title":"奉送相公十八丈镇杨州","author":"李德裕","dynasty":"唐","verses":["千骑风生大斾舒，春江重到武侯庐。","共悬龟印衔新绶，同忆鳣庭访旧居。","取履桥边啼鸟换，钓璜溪畔落花初。","今来却笑临邛客，入蜀空驰使者车。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-2effbb1c-0785-47f0-8440-43e4c1c893ec","tags":[]},{"id":"poem-7d4c0da03e1fe82f0d0a495c","title":"郊庙歌辞 释奠武成王乐章 迎神","author":"于邵","dynasty":"唐","verses":["卜畋不从，兆发非熊。","乃倾荒政，爰佐一戎。","盛烈载垂，命祀惟崇。","日练上戊，宿严閟宫。","迎奏嘉至，感而遂通。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-07dfbf80-7b02-4ce1-8bf5-db426350aeed","tags":[]},{"id":"poem-7d583d612d9fa8d44847a126","title":"陈宣卿为予作后雕图","author":"陈造","dynasty":"宋","verses":["吾宗洒画墨，似我诗得趣。","未至心手忘，敢议江山助。","东绢十幅围，中有千尺树。","穷冬万虫蛰，拆地双虬怒。","仿佛风雨声，想像栋梁具。","人间汗反浆，对此毛发竖。","怪君物写影，落笔神与遇。","自言阅世孰，妙解等僧悟。","每当槃薄余，了知精灵聚。","此图尤杰出，持用博新句。","墨君第一流，论世无殆庶。","三熏且十袭，复靳为子赋。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-05324d67-5942-4304-80a9-f97c0d8d9426","tags":[]},{"id":"poem-7d5ecd861d073eac9ad25ce4","title":"代农答别乘劝耕  其一","author":"释居简","dynasty":"宋","verses":["敢忘百拜与三行，非贾非工只得耕。","旧不便民毋助长，新非怫众却休更。","验今多是迂扶曲，考古无非直胜横。","只把襦歌征别乘，不从谏议问苍生。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-e904ef91-42ba-42c0-89da-75dfb69e6fb6","tags":[]},{"id":"poem-7d63fb30dd66dec37e60e5da","title":"余文","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["向人家，忙投奔，解鞍沽酒共论文，今夜雨打梨花深闭门。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4975","tags":[]},{"id":"poem-7d66769b6aeb183360e23d83","title":"正月十五日","author":"熊孺登","dynasty":"唐","verses":["汉家遗事今宵见，楚郭明灯几处张。","深夜行歌声绝后，紫姑神下月苍苍。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-6eeef00c-d99d-4f78-8d1b-e68dda63d885","tags":[]},{"id":"poem-7d687f78ad273f23da4bdc0d","title":"送客往鄜州","author":"杨凝","dynasty":"唐","verses":["新参将相事营平，锦带骍弓结束轻。","晓上关城吟画角，暗驰羗马发支兵。","回中地近风常急，鄜畤年多草自生。","近喜扶阳系戎相，从来衞霍笑长缨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-79f78a30-4013-4ecf-ac2f-93fa0b234ecb","tags":[]},{"id":"poem-7d6da382d97e14c9e68dcd26","title":"酬终南阎谏议见寄","author":"司马光","dynasty":"宋","verses":["齿衰心力耗，揣分乞西台。","微禄供多病，闲官养不才。","弊庐容啸傲，清洛伴归来。","故友犹相念，寒光生死灰。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-99ca811b-e54c-48f5-87b0-599c429e9729","tags":[]},{"id":"poem-7d7f5dd02c9dd7b1f964a579","title":"西施·苎萝妖艳世难偕","author":"柳永","dynasty":"宋","verses":["苎萝妖艳世难偕。","善媚悦君怀。","后庭恃宠，尽使绝嫌猜。","正恁朝欢暮宴，情未足，早江上兵来。","捧心调态军前死，罗绮旋变尘埃。","至今想，怨魂无主尚徘徊。","夜夜姑苏城外，当时月，但空照荒台。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-216","tags":[]},{"id":"poem-7d8045dd30a1171564f0a5aa","title":"题从叔沆林园","author":"李端","dynasty":"唐","verses":["阮宅闲园暮，窗中见树阴。","樵歌依远草，僧语过长林。","鸟哢花间曲，人弹竹里琴。","自嫌身未老，已有住山心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-31f756f8-7fbd-47f7-852b-5d15bccede9a","tags":[]},{"id":"poem-7d84a16b53bc44508d676e6f","title":"酬韩祭酒雨中见寄","author":"张籍","dynasty":"唐","verses":["雨中愁不出，阴黑尽连宵。","屋湿唯添漏，泥深未放朝。","无刍怜马瘦，少食信儿娇。","闻道韩夫子，还同此寂寥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-0a1d7258-c61a-484e-a98c-49a7f09f3825","tags":[]},{"id":"poem-7d889926d1b369e67fae1f90","title":"别杜将军","author":"贯休","dynasty":"唐","verses":["伊余本是胡为者，采蕈锄茶在穷野。","偶披蓑笠事空王，余力为文拟何谢。","少年心在青云端，知音满地皆龙鸾。","遽逢天步艰难日，深藏溪谷空长叹。","偶出重围遇英哲，留我江楼经岁月。","身隈玉帐香满衣，梦历金盆雨和雪。","东风来兮歌式微，深云道人召来归。","燕辞大厦兮将何为，蒙蒙花雨兮莺飞飞，一汀杨柳同依依。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-f235b793-9b94-4451-a5c4-14b30ed54060","tags":[]},{"id":"poem-7d8b574f04447a74344ae209","title":"长亭怨・长亭怨慢·泛孤艇、东皋过遍","author":"王沂孙","dynasty":"宋","verses":["泛孤艇、东皋过遍。","尚记当日，绿阴门掩。","屐齿莓阶，酒痕罗袖事何限。","欲寻前迹，空惆怅、成秋苑。","自约赏花人，别后总、风流云散。","水远。","怎知流水外，却是乱山尤远。","天涯梦短。","想忘了、绮疏雕槛。","望不尽、苒苒斜阳，抚乔木、年华将晚。","但数点红英，犹识西园凄婉。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-253","tags":["宋词三百首"]},{"id":"poem-7d9400fddd819b36524f6276","title":"水调歌头·湖海倦游客","author":"张孝祥","dynasty":"宋","verses":["湖海倦游客，江汉有归舟。","西风千里，送我今夜岳阳楼。","日落君山云气，春到沅湘草木，远思渺难收。","徙倚栏杆久，缺月挂帘钩。","雄三楚，吞七泽，隘九州。","人间好处，何处更似此楼头。","欲吊沈累无所，但有渔儿樵子，哀此写离忧。","回首叫虞舜，杜若满芳洲。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-386","tags":["岳阳楼"]},{"id":"poem-7d94e23577141860331c2c96","title":"咏史诗 铜柱","author":"胡曾","dynasty":"唐","verses":["一柱高标险塞垣，南蛮不敢犯中原。","功成自合分茅土，何事翻衔薏苡冤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-54405bf9-eca3-4359-8277-360a11b913cb","tags":[]},{"id":"poem-7d9890b8d538cb47c228fc78","title":"送重钧上人游天台","author":"皎然","dynasty":"唐","verses":["渐看华顶出，幽赏意随生。","十里行松色，千重过水声。","海容云正尽，山色雨初晴。","事事将心证，知君道可成。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-0dc1a905-638b-4ee0-b6cf-8b958bc3ea64","tags":[]},{"id":"poem-7d9e8085bfae3161192ed78a","title":"小游仙诗九十八首 四十九","author":"曹唐","dynasty":"唐","verses":["采女平明受事回，暗交丹契锦囊开。","欲书密诏防人见，佯喝青虬使莫来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-67960cbc-c0e6-49f0-a82f-96ed3a4e949e","tags":[]},{"id":"poem-7d9ee5cecbcc514989632f82","title":"醉花阴·弧门此日犹能记","author":"王之望","dynasty":"宋","verses":["弧门此日犹能记。","叹居诸难系。","弹指片声中，不觉流年，五十还加二。","儿童寿酒邀翁醉。","笑欣欣相戏。","休画老人星，白发苍髯，怎解如翁似。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-491","tags":[]},{"id":"poem-7db12d6e06ad89960d8a419b","title":"喜友人再面","author":"裴说","dynasty":"唐","verses":["一别几寒暄，迢迢隔塞垣。","相思长有事，及见却无言。","静坐将茶试，闲书把叶翻。","依依又留宿，圆月上东轩。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-db5620d2-67d1-4e8a-b39b-bb9e0ccf9b84","tags":[]},{"id":"poem-7db55d39018b61e015df2b52","title":"于中好·谁道阴山行路难","author":"纳兰性德","dynasty":"清","verses":["谁道阴山行路难。","风毛雨血万人欢。","松梢露点沾鹰绁，芦叶溪深没马鞍。","依树歇，映林看。","黄羊高宴簇金盘。","萧萧一夕霜风紧，却拥貂裘怨早寒。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-130","tags":[]},{"id":"poem-7dc67f38d3dada680c6c89d4","title":"和复古小园书事","author":"司马光","dynasty":"宋","verses":["饱食复闲眠，风清雨霁天。","叶深时坠果，岸曲乍藏莲。","波面秋光浄，林梢夕照鲜。","东家近亦富，满地布苔钱。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-b104b09b-0cad-4e06-a72e-8fa04a37b2b1","tags":[]},{"id":"poem-7dc709201fe25593ad82f758","title":"送韦评事归华阴","author":"张籍","dynasty":"唐","verses":["三峰西面住，出见世人稀。","老大谁相识，恓惶又独归。","埽窗秋菌落，开箧夜蛾飞。","若向云中伴，还应着褐衣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-91a0cff0-9b7f-4241-8980-5f0d6ef4b35b","tags":[]},{"id":"poem-7dc9f957def75723ba942fff","title":"桐竹赠张燕公","author":"李伯鱼","dynasty":"唐","verses":["北竹青桐北，南桐绿竹南。","竹林君早爱，桐树我初贪。","凤栖桐不媿，凤食竹何慙。","栖食更如此，余非凤所堪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-b11c0a85-b5f4-4f3f-b2b1-37f1246c6347","tags":[]},{"id":"poem-7dde1e8ae467dfa19001a67f","title":"寄旧友二首  其二","author":"宋伯仁","dynasty":"宋","verses":["微官宁得似穷儒，俛首逢迎气不舒。","便是伐薪能煮海，何如烧叶自观书。","半蓬寒雨苕溪酒，一线西风震泽鱼。","但得此身无系束，江南有地著顽疎。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-b23e3bdc-1052-4e73-8125-ff0966202c40","tags":[]},{"id":"poem-7de9786f7f1340fbaeadafc9","title":"题松汀驿","author":"张佑","dynasty":"唐","verses":["山色远含空，苍茫泽国东。","海明先见日，江白迥闻风。","鸟道高原去，人烟小径通。","那知旧遗逸，不在五湖中。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-題鬆汀驛","tags":[]},{"id":"poem-7df21f3215657c639f724e1c","title":"景山","author":"纳兰性德","dynasty":"清","verses":["雪里瑶华岛，云端白玉京。","削成千仞势，高出九重城。","绣陌回环绕，红楼宛转迎。","近天多雨露，草木每先荣。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-248","tags":[]},{"id":"poem-7df3517c13ff19bdc4df3c5d","title":"冬日游览","author":"王维","dynasty":"唐","verses":["步出城东门，试骋千里目。","青山横苍林，赤日团平陆。","渭北走邯郸，关东出函谷。","秦地万方会，来朝九州牧。","鸡鸣咸阳中，冠盖相追逐。","丞相过列侯，群公饯光禄。","相如方老病，独归茂陵宿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-d0e4fe3e-e066-4dfb-97d3-ec55f756c172","tags":[]},{"id":"poem-7e11ce64fea4c921d884b79e","title":"风流子·新绿小池塘","author":"周邦彦","dynasty":"宋","verses":["新绿小池塘。","风帘动，碎影舞斜阳。","羡金屋去来，旧时巢燕，土花缭绕，前度莓墙。","绣阁凤帏深几许，曾听得理丝簧。","欲说又休，虑乖芳信，未歌先咽，愁近清觞。","遥知新妆了，开朱户，应自待月西厢。","最苦梦魂，今宵不到伊行。","问甚时说与，佳音密耗，寄将秦镜，偷换韩香。","天便教人，霎时厮见何妨。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-225","tags":["宋词三百首"]},{"id":"poem-7e1a22ccc1fcdf498f9d8f36","title":"横吹曲辞 折杨柳","author":"卢照邻","dynasty":"唐","verses":["倡楼启曙扉，园柳正依依。","鸟鸣知岁隔，条变识春归。","露叶疑啼脸，风花乱舞衣。","攀折聊将寄，军中书信稀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-70b41da6-9b4d-4392-b0fb-23ef70a1cd78","tags":[]},{"id":"poem-7e1bc77978c42fda545e485a","title":"鴈汊东守风四首  其三","author":"陈造","dynasty":"宋","verses":["惊麋砀洪浸，何人矢丽龟。","遂令老病叟，珍毳及晚炊。","野鹿敢伯仲，江鲟让甘肥。","淮人笃乡义，贱乞等韭葵。","向来无人境，沙漫水无涯。","市声不到耳，茭苇相因依。","今无暴客虞，解衣候朝曦。","厚味真过矣，安食如含饴。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-975823af-be04-4ed5-be4e-5638fc969306","tags":[]},{"id":"poem-7e204fb773c5772bb4ba3132","title":"郊庙歌辞 祀圜丘乐章 雍和","author":"褚亮","dynasty":"唐","verses":["钦惟大帝，[载]仰皇穹。","始命田烛，爰启郊宫。","云门骇听，雷鼓鸣空。","神其介祀，景祚斯融。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-92a8846f-c399-4145-a36b-4b8c0b7d9c14","tags":[]},{"id":"poem-7e20d967473bcf235f025bd7","title":"小旻","author":"佚名","dynasty":"先秦","verses":["旻天疾威，敷于下土。谋犹回遹，何日斯沮？谋臧不从，不臧覆用。我视谋犹，亦孔之邛。","潝潝訿訿，亦孔之哀。谋之其臧，则具是违。谋之不臧，则具是依。我视谋犹，伊于胡厎。","我龟既厌，不我告犹。谋夫孔多，是用不集。发言盈庭，谁敢执其咎？如匪行迈谋，是用不得于道。","哀哉为犹，匪先民是程，匪大犹是经。维迩言是听，维迩言是争。如彼筑室于道谋，是用不溃于成。","国虽靡止，或圣或否。民虽靡膴，或哲或谋，或肃或艾。如彼泉流，无沦胥以败。","不敢暴虎，不敢冯河。人知其一，莫知其他。战战兢兢，如临深渊，如履薄冰。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-194","tags":[]},{"id":"poem-7e229550ac91805cbc3353eb","title":"浣溪沙·残雪凝辉冷画屏","author":"纳兰性德","dynasty":"清","verses":["残雪凝辉冷画屏，落梅横笛已三更，更无人处月胧明。","我是人间惆怅客，知君何事泪纵横，断肠声里忆平生。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-23","tags":[]},{"id":"poem-7e23c4c5976a8f0665db1bf0","title":"内宴奉诏作","author":"曹翰","dynasty":"宋","verses":["三十年前学六韬，英名常得预时髦。","曾因国难披金甲，不为家贫卖宝刀。","臂健尚嫌弓力软，眼明犹识阵云高。","庭前昨夜秋风起，羞睹盘花旧战袍。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-72ced332-bb34-4ae3-aff1-d1ffedee6226","tags":[]},{"id":"poem-7e2a6812cd5f4cff5fd5bb0b","title":"放萤怨","author":"刘言史","dynasty":"唐","verses":["放萤去，不须留，聚时年少今白头。","架中科斗万余卷，一字千回重照见。","青云杳渺不可亲，开囊欲放增余怨。","且逍遥，还酩酊，仲舒漫不窥园井。","那将寂寞老病身，更就微虫借光影。","欲放时，泪沾裳，冲篱落，千点光。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-97bdc1a3-da7a-46b1-a6f3-effdb768335c","tags":[]},{"id":"poem-7e31c1622c7a2b1f5aec7e70","title":"寄东蜀幕中友","author":"李洞","dynasty":"唐","verses":["官亭池碧海榴殷，遥想清才倚画栏。","柳絮涨天笼地暖，角声经雨透云寒。","晓侵台座香烟湿，夜草军书蜡炬干。","为话门人吟太苦，风摧兰秀一枝残。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-865ff86d-2470-48ad-998e-180aff28b34f","tags":[]},{"id":"poem-7e42daaf31b875a93a977565","title":"寄徽州谢使君密斋","author":"释居简","dynasty":"宋","verses":["新安产最良，引类赴文房。","太守五四友，管城三二王。","水分千里月，春满六州棠。","丹穴皆鲜羽，丛霄看颉颃。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-66f21eed-0f8a-4129-9131-a458dc448512","tags":[]},{"id":"poem-7e465ce486ef70756df4d6e9","title":"上平江徐侍郎十绝句  其四","author":"曾协","dynasty":"宋","verses":["并列西京侍从多，吾丘司马岂同科。","孤忠祇有囊书在，独见丁宁为偃戈。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-2c875802-153c-4cb7-b0e1-66affb8b0dbe","tags":[]},{"id":"poem-7e4a71519a7b0d1b1890125a","title":"字字双","author":"无名氏《张协状元》","dynasty":"元","verses":["一石两石米和谷，也一担担。","两桶三桶臭物事，也一担担。","四把五把大枥柴，也一担担。","豆腐一头酒一头，也一担担。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2516","tags":[]},{"id":"poem-7e4b33471745022ad2f1c323","title":"郊庙歌辞 享太庙乐章 雍和二章 二","author":"张说","dynasty":"唐","verses":["俎豆有馥，粢盛絜丰。","亦有和羹，既戒既平。","鼓钟管磬，肃唱和鸣。","皇皇后祖，来我思成。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-7196811a-78b3-4b37-b38d-4f312579860c","tags":[]},{"id":"poem-7e4d520272d134e488f2460f","title":"水调歌头·华栋一何丽","author":"仲并","dynasty":"宋","verses":["华栋一何丽，移下小壶天。","几多曲房新户，缥缈似当年。","曾是使君风度，元有胸中丘壑，六月竹风寒。","一洗筝笛耳，歌舞粲筵间。","坐中客，醒复醉，听无眠。","已回归梦，犹复袅袅记清圆。","尚想饮中仙子，来处馀香飘坐，胜韵此双全。","为寄月华语，难与并蝉娟。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-200","tags":[]},{"id":"poem-7e502a3a870642c58e51140d","title":"通衢驿夜坐有感二首  其一","author":"李纲","dynasty":"宋","verses":["永夜发孤笑，起看河汉流。","群山涌翠浪，纤月挂琼钩。","岂谓艰难日，翻成汗漫游。","虚舟全不系，暮景付沧洲。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-6b7f8ac5-5bf9-4c68-9d17-47532a1f3a6d","tags":[]},{"id":"poem-7e61121b803e7930db879ef5","title":"清平乐·彩舟双橹","author":"蔡伸","dynasty":"宋","verses":["彩舟双橹。","六月临平路。","小雨轻风消晚暑。","绕岸荷花无数。","玉人璨枕方床。","遥知待月西厢。","昨夜有情风月，今宵特地凄凉。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-989","tags":[]},{"id":"poem-7e67f9a0483812007c284ca7","title":"暖斋诗","author":"华镇","dynasty":"宋","verses":["至足无求触处同，小斋和气日冲融。","几筵已得啸歌地，赤白何须绘画工。","况有午簷容爱日，曾无北户召寒风。","清心迥出尘埃外，讵见高堂数仞崇。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-2b04f569-e547-4b68-91b7-231e89dd77c3","tags":[]},{"id":"poem-7e69f03789d54c139f615d17","title":"金缕曲·慰西溟","author":"纳兰性德","dynasty":"清","verses":["何事添凄咽。","但由他、天公簸弄，莫教磨涅。","失意每多如意少，终古几人称屈。","须知道、福因才折。","独卧藜床看北斗，背高城、玉笛吹成血。","听谯鼓，二更彻。","丈夫未肯因人热，且乘闲、五湖料理，扁舟一叶。","泪似秋霖挥不尽，洒向野田黄蝶。","须不羡、承明班列。","马迹车尘忙未了，任西风吹冷长安月。","又萧寺，花如雪。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-129","tags":[]},{"id":"poem-7e705fbb5d0fd5288c76497b","title":"石桥","author":"陶谷","dynasty":"唐","verses":["重重翠嶂耸云端，玉殿金楼缥缈间。","圣境不容凡俗到，故将飞瀑隔尘寰。","（见《天台续集》卷中。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-0c615de4-40a9-469a-bbf4-4f341bdb6d57","tags":[]},{"id":"poem-7e70ec3d6d3cfd1547af9970","title":"韩寺遗墟","author":"释居简","dynasty":"宋","verses":["十年秋傍故山零，一坞残云夜不扃。","土偶向人犹作祟，相传不似旧时灵。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-9fc161b5-5a81-40fb-b1d5-e0d388573a9c","tags":[]},{"id":"poem-7e70f9049cd2663461180337","title":"芦花","author":"雍裕之","dynasty":"唐","verses":["夹岸复连沙，枝枝摇浪花。","月明浑似雪，无处认渔家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-6c1ba143-42bb-453d-9c93-cd2ae33423d2","tags":["咏物诗","花","咏物","写花"]},{"id":"poem-7e71556acbecb1524e0750c1","title":"发成都  其一","author":"刘望之","dynasty":"宋","verses":["落拓平生载酒行，如今憔悴鬓丝生。","无金得买青楼笑，空负闲愁出锦城。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-9aa858b3-e439-4156-8b7e-79726de6b0ec","tags":[]},{"id":"poem-7e75eb29c7b88ba0e26bdf75","title":"寒食书事","author":"赵鼎","dynasty":"宋","verses":["寂寂柴门村落里，也教插柳纪年华。","禁烟不到粤人国，上冢亦携庞老家。","汉寝唐陵无麦饭，山溪野径有梨花。","一樽竟藉青苔卧，莫管城头奏暮笳。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-寒食書事","tags":[]},{"id":"poem-7e7b9c62a89183fd1bae2ee2","title":"山居八咏 五","author":"常达","dynasty":"唐","verses":["真性寂无机，尘尘祖佛师。","日明庭砌暖，霜苦药苗衰。","汲水和烟酌，栽松带雪移。","好听玄旨处，猨啸岭南枝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-1af19b68-1a4b-443d-bb19-b6a5bde4dd78","tags":[]},{"id":"poem-7e95e1218317db6e40b43dfa","title":"寄畅当","author":"李端","dynasty":"唐","verses":["麦秀草芊芊，幽人好昼眠。","云霞生岭上，猿鸟下床前。","颜子方敦行，支郎久住禅。","中林轻暂别，约略已经年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-51169d5f-1218-48cf-873a-c2851aa0c9b7","tags":[]},{"id":"poem-7ea19ae7cad568c0a0cf3e9f","title":"别","author":"徐夤","dynasty":"唐","verses":["酒尽歌终问后期，泛萍浮梗不胜悲。","东门匹马夜归处，南浦片帆飞去时。","赋罢江淹吟更苦，诗成苏武思何迟。","可怜范陆分襟后，空折梅花寄所思。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-059c7799-21ec-43fc-b21f-96d763b83f58","tags":[]},{"id":"poem-7ea2a0af0efd112301f7f275","title":"谢公石罇","author":"李翔","dynasty":"唐","verses":["康乐云楼迹尚存，竹亭犹仰古洼罇。","苔封四面迷山象，露滴中心认酒痕。","岩月旧来曾伴饮，涧泉今咽共谁论。","无因访得逃尧客，求取风瓢挂石门。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-952663f4-dcc2-4359-87fc-bdc6cb8ab378","tags":[]},{"id":"poem-7ea5c7955042c7b99781e9c3","title":"别赞上人","author":"杜甫","dynasty":"唐","verses":["百川日东流，客去亦不息。","我生苦漂荡，何时有终极。","赞公释门老，放逐来上国。","还为世尘婴，颇带顦顇色。","杨枝晨在手，豆子雨已熟。","是身如浮云，安可限南北。","异县逢旧友，初忻写胸臆。","天长关塞寒，岁暮饥冻逼。","野风吹征衣，欲别向曛黑。","马嘶思故枥，归鸟尽敛翼。","古来聚散地，宿昔长荆棘。","相看俱衰年，出处各努力。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-40de2a56-327b-49db-894d-dbf8735ad3a8","tags":[]},{"id":"poem-7ea607a5cbd2e5141b7e73c0","title":"三","author":"王梵志","dynasty":"唐","verses":["兄弟相怜爱，同生莫异居。","为人欲得别，（「人」，伯三六五六卷作「若」。","）此则是兵奴。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-041d246a-3b2e-4a83-91c9-2e60952dc3a1","tags":[]},{"id":"poem-7ea77dbf2c72b7f0b03cbe67","title":"永明山居诗（六十九首） 七","author":"延寿","dynasty":"唐","verses":["事多兴废莫持论，唯有禅宗理可尊。","似讷始平分别路，如愚方塞是非门。","刳肠祇为生灵智，剖舌多因强语言。","争似息机高卧客，年来年去道长存。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-7c591022-b55d-41eb-af3a-adee927a9fab","tags":[]},{"id":"poem-7eb1a75c2d0401bf3f450524","title":"却东西门行","author":"曹操","dynasty":"汉","verses":["鸿雁出塞北，乃在无人乡。","举翅万馀里，行止自成行。","冬节食南稻，春日复北翔。","田中有转蓬，随风远飘扬。","长与故根绝，万岁不相当。","奈何此征夫，安得驱四方！","戎马不解鞍，铠甲不离傍。","冉冉老将至，何时返故乡？","神龙藏深泉，猛兽步高冈。","狐死归首丘，故乡安可忘！"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-12","tags":[]},{"id":"poem-7eb2ec8510eee012bfbd97fb","title":"九江暮春书事","author":"曹松","dynasty":"唐","verses":["杨柳城初鏁，轮蹄息去踪。","春流无旧岸，夜色失诸峰。","影动渔边火，声迟话后钟。","明朝廻去鴈，谁向北郊逢。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-01be89cd-516b-4fb0-a4ba-4a6af88d2c66","tags":[]},{"id":"poem-7eb5f812c3d79cca0d1e6e31","title":"念奴娇·萧条庭院","author":"李清照","dynasty":"宋","verses":["萧条庭院，有斜风细雨，重门须闭。","宠柳娇花寒食近，种种恼人天气。","险韵诗成，扶头酒醒，别是闲滋味。","征鸿过尽，万千心事难寄。","楼上几日春寒，帘垂四面，玉阑干慵倚。","被冷香消新梦觉，不许愁人不起。","清露晨流，新桐初引，多少游春意。","日高烟敛，更看今日晴未。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-202","tags":["宋词三百首"]},{"id":"poem-7eba3d530630c5c4283b0738","title":"浪淘沙·秋杪喜新凉","author":"曹勋","dynasty":"宋","verses":["秋杪喜新凉。","烟淡池塘。","团团岩桂作风光。","多少水云萧散意，都付芬芳。","雨逐漏声长。","小院回廊。","枕边清梦几悠扬。","只恐四檐声未断，洗褪幽香。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-174","tags":[]},{"id":"poem-7ecc8bf51a5babe8e0fbcc17","title":"小重山·秋到长门秋草黄","author":"薛昭蕴","dynasty":"五代","verses":["秋到长门秋草黄，画梁双燕去，出宫墙。","玉箫无复理霓裳，金蝉坠，鸾镜掩休妆。","忆昔在昭阳，舞衣红绶带，绣鸳鸯。","至今犹惹御炉香，魂梦断，愁听漏更长。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-38","tags":[]},{"id":"poem-7ed3448a2874f7a4b78fd3f6","title":"沉醉东风","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["你爹行见得你好偏，只一子不留在身畔。","(介)我和你去说咱。","休休，他只道我不贤，要将你迷恋。","苦！这其间怎不悲怨？(合)为爹泪涟，为娘泪涟，何曾为着夫妻上意牵？(生唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4944","tags":[]},{"id":"poem-7ed9dffabd186a7201911e06","title":"柳条边","author":"纳兰性德","dynasty":"清","verses":["是处垣篱防绝塞，角端西来画疆界。","汉使今行虎落中，秦城合筑龙荒外。","龙荒虎落两依然，护得当时饮马泉。","若使春风知别苦，不应吹到柳条边。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-229","tags":[]},{"id":"poem-7eda8cfd5016dc6b07bd0f01","title":"听董大弹胡笳声兼寄语弄房给事","author":"李颀","dynasty":"唐","verses":["蔡女昔造胡笳声，一弹一十有八拍。","胡人落泪沾边草，汉使断肠对归客。","古戍苍苍烽火寒，大荒沈沈飞雪白。","先拂商弦后角羽，四郊秋叶惊摵摵。","董夫子，通神明，深山窃听来妖精。","言迟更速皆应手，将往复旋如有情。","空山百鸟散还合，万里浮云阴且晴。","嘶酸雏鴈失群夜，断绝胡儿恋母声。","川为净其波，鸟亦罢其鸣。","乌孙部落家乡远，逻娑沙尘哀怨生。","幽音变调忽飘洒，长风吹林雨堕瓦。","迸泉飒飒飞木末，野鹿呦呦走堂下。","长安城连东掖垣，凤凰池对青琐门。","高才脱略名与利，日夕望君抱琴至。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-361a3e5e-ef71-4749-b39a-aa2f5d9180e4","tags":["唐诗三百首","长诗","七言古诗","抒情","古体"]},{"id":"poem-7edc3d008db93cb401b1f781","title":"杨柳枝·烂漫春归水国时","author":"皇甫松","dynasty":"唐","verses":["烂漫春归水国时，吴王宫殿柳丝垂。","黄莺长叫空闺畔，西子无因更得知。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-21","tags":[]},{"id":"poem-7ee0dc6cd65489e00b007809","title":"咏萤","author":"周繇","dynasty":"唐","verses":["熠熠与娟娟，池塘竹树边。","乱飞同曳火，成聚却无烟。","微雨洒不灭，清风吹欲燃。","旧曾书按上，频把作囊悬。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-a4dea634-027d-45fc-908b-5372ec05fc91","tags":[]},{"id":"poem-7ee65dbb82c9ec13650bfbd7","title":"方岩王侍郎江西破贼归  其二","author":"释居简","dynasty":"宋","verses":["左蠡扬澜草葑湖，轴轳啣尾碍前驱。","苇航折叠多余地，潜伏骞腾在卷舒。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-a9ce05eb-7cef-494b-8a9c-561fbde851d8","tags":[]},{"id":"poem-7ee7d12744be0bffa95fa7f9","title":"禹庙","author":"杜甫","dynasty":"唐","verses":["禹庙空山里，秋风落日斜。","荒庭垂橘柚，古屋画龙蛇。","云气生虚壁，江深走白沙。","早知乘四载，疏凿控三巴。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-禹廟","tags":[]},{"id":"poem-7eeb7408f3e00922c29f801c","title":"送豆卢策归别墅","author":"孟郊","dynasty":"唐","verses":["短松鹤不巢，高石云不栖。","君今潇湘去，意与云鹤齐。","力买奇险地，手开清浅溪。","身披薜荔衣，山陟莓苔梯。","一卷冰雪文，避俗常自携。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-7f7f9ddf-5c2d-4d93-ac43-d2e1ca1c3e2e","tags":[]},{"id":"poem-7ef5c636b4bb84ee8631ca8f","title":"偷声木兰花·雪笼琼苑梅花瘦","author":"张先","dynasty":"宋","verses":["雪笼琼苑梅花瘦。","外院重扉联宝兽。","海月新生。","上得高楼无奈情。","帘波不动凝釭小。","今夜夜长争得晓。","欲梦高唐。","只恐觉来添断肠。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-349","tags":[]},{"id":"poem-7efb3e15fea9745e31785bd5","title":"冬日作","author":"裴说","dynasty":"唐","verses":["粝食拥败絮，苦吟吟过冬。","稍寒人却健，太饱事多慵。","树老生烟薄，墙阴贮雪重。","安能只如此，公道会相容。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-8d47db03-2ee3-4555-8cb3-5bcb164cdf2c","tags":[]},{"id":"poem-7efc73ba3596ce4b526dbffc","title":"遣兴次前韵","author":"陈造","dynasty":"宋","verses":["斫水蕲断流，捻盐宁疗渴。","区区守荒学，笼鸟眩樊遏。","向来麋鹿姿，祇可樵牧活。","始其事诵数，魄似穷鬼夺。","文字取憎疾，见谓蜩螗聒。","回首辈行人，班剑或朝谒。","方嗟沈带减，正坐河鱼孽。","分无青云上，但有枯策阅。","峩峩指顶地，群口免骚屑。","醪敷儿为供，蜜脾手亲割。","敝帚非世用，槁梧取己说。","非君莫逆者，此怀谁与说。","反求每日诳，百行收一节。","西来倾藁册，又满三百叶。","暮年了无得，付子镜中雪。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-18abfdb9-6625-47fb-9f29-53d5fdd6a60b","tags":[]},{"id":"poem-7f0dedc8e4d862292f0b831d","title":"春情","author":"杨凭","dynasty":"唐","verses":["暮雨朝云几日归，如丝如雾湿人衣。","三湘二月春光早，莫逐狂风缭乱飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-16b22371-368d-4d3c-90ee-dff0c3d16670","tags":[]},{"id":"poem-7f13896db2e331d2949930b8","title":"登开元宫德和楼","author":"王镃","dynasty":"宋","verses":["瑞云深处碧玲珑，得道高人在此中。","玉树影迷唐旧邸，金钟声绕汉诸宫。","夜看西北天星近，晓对东南海日红。","咫尺便分仙俗路，吴山斜出锦屏风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-45e1a2ac-4cac-4558-9186-d2adc8302200","tags":[]},{"id":"poem-7f166186234d01c098eba5c7","title":"抒情因上郎中二十二叔监察十五叔兼呈李益端公柳缜评事","author":"孟郊","dynasty":"唐","verses":["方凭指下弦，写出心中言。","寸草贱子命，高山主人恩。","游边风沙意，梦楚波涛魂。","一日引别袂，九回沾泪痕。","自悲何以然，在礼阙晨昏。","名利时转甚，是非宵亦喧。","浮情少定主，百虑随世翻。","举此胸臆恨，幸从贤哲论。","明明三飞鸾，照物如朝暾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-5a9e3e53-cd89-43f4-a90f-f9f21e52899a","tags":[]},{"id":"poem-7f1c1c7cc72f25f98c965823","title":"枉系二首 一","author":"沈佺期","dynasty":"唐","verses":["吾怜曾家子，昔有投杼疑。","吾怜姬公旦，非无鸱鸮诗。","臣子竭忠孝，君亲惑谗欺。","萋斐离骨肉，含愁兴此辞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-dfda4102-2446-4daa-a7bb-1539ec77c5d3","tags":[]},{"id":"poem-7f318ec3688ebb0fe5140264","title":"渡汉江","author":"李频","dynasty":"唐","verses":["岭外音书绝，经年复历春。","近乡情更怯，不敢问来人。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-a6144ae0-3bcf-4503-b58d-9abf24d6608c","tags":["五言绝句","思乡","唐诗三百首","渡江"]},{"id":"poem-7f39560b48b2120de5b11571","title":"送吴冯游京","author":"皎然","dynasty":"唐","verses":["北期何意促，蕙草夜来繁。","清月思淮水，春风望国门。","此时休旋逸，万里忽飞翻。","若忆山阴会，孤琴为我援。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-4a4243ce-d7ea-4524-b1bc-afdbccb75945","tags":[]},{"id":"poem-7f3c243f38428e90caadc6fe","title":"虞美人·红窗寂寂无人语","author":"孙光宪","dynasty":"五代","verses":["红窗寂寂无人语，暗淡梨花雨。","绣罗纹地粉新描，博山香炷旋抽条，暗魂消。","天涯一去无消息，终日长相忆。","教人相忆几时休？不堪枨触别离愁，泪还流。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-7","tags":[]},{"id":"poem-7f49fe4630f9aef163779ec6","title":"塞下曲 四","author":"李益","dynasty":"唐","verses":["为报如今都护雄，匈奴且莫下云中。","请书塞北阴山石，愿比燕然车骑功。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-04b1e32a-44da-4530-b953-2db87e4c9d5e","tags":[]},{"id":"poem-7f514b8fc06d8aa7d5214642","title":"润州听暮角","author":"李涉","dynasty":"唐","verses":["江城吹角水茫茫，曲引边声怨思长。","惊起暮天沙上鴈，海门斜去两三行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-cd1d93ca-b688-4ec1-a1e6-c4cf880695b7","tags":["抒情","写景"]},{"id":"poem-7f53e439ca65a0755b57b3af","title":"将归江淮书","author":"张乔","dynasty":"唐","verses":["东风摇众木，即有看花期。","紫陌频来日，沧洲独去时。","郡因兵役苦，家为海翻移。","未老多如此，那堪鬓不衰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-dc37c875-1e11-4ad6-b196-85581c174787","tags":[]},{"id":"poem-7f551d8edfff4f6d06f04826","title":"次王彦昭寄苏景谟青社园亭韵二首  其二","author":"刘跂","dynasty":"宋","verses":["谁道前贤迹已尘，园林气象迩来新。","高山流水有深意，翠竹黄花如故人。","小队郊坰时访客，后堂歌吹独留宾。","汶阳寂寞无佳赏，卧阁萧然过一春。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-8332a448-e8de-4470-874e-f9a49c9daf56","tags":[]},{"id":"poem-7f58695b14c9d08062243a1f","title":"终南山","author":"王维","dynasty":"唐","verses":["太乙近天都，连山接海隅。","白云回望合，青霭入看无。","分野中峰变，阴晴众壑殊。","欲投人处宿，隔水问樵夫。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-a5b1f5c9-1ba7-4533-b497-55b1d4af1bbb","tags":["唐诗三百首","终南山","一年级下册","五言律诗","高中古诗","描写山","写山"]},{"id":"poem-7f5cbe821bb4d392102c1e17","title":"江行夜雨","author":"张乔","dynasty":"唐","verses":["江风木落天，游子感流年。","万里波连蜀，三更雨到船。","梦残灯影外，愁积苇业边。","不及樵渔客，全家住岛田。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-a57286cf-5bc2-4dc1-ab2c-2ef9b08686a1","tags":[]},{"id":"poem-7f5f9a2138d60efce8102534","title":"昭君怨","author":"顾朝阳","dynasty":"唐","verses":["莫将铅粉匣，不用镜花光。","一去边城路，何情更画妆。","影销胡地月，衣尽汉宫香。","妾死非关命，都缘怨断肠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-732e42d4-1fdf-4485-8c32-4cede895edc9","tags":[]},{"id":"poem-7f6333684fd4cb3f59356e63","title":"续当涂别驾林率庵赋谪仙李翰林","author":"释居简","dynasty":"宋","verses":["龊龊复龊龊，未死如未生。","公去月明在，留得青山茔。","青山倚公高，屹立千载英。","翠𪩘拓吟垒，飞瀑按酒兵。","行客一仰止，折几鄙吝萌。","狂歌长短吟，迈古日月明。","俊逸兼鲍谢，丽则侪云卿。","骅骝博艳姬，土苴群方兄。","节峻玄霜严，义重紫禁轻。","酹土土长燥，雷魁何由平。","生男禁多才，此话闻阿庚。","真才弃如土，大厦谁支倾。","不用谢安石，大雅空垂名。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-3d5553d9-f853-463f-b3e7-dac9de20774b","tags":[]},{"id":"poem-7f644443d620a9226b6d075c","title":"台州兜率寺淳熙三年孟春作  其四","author":"林宪","dynasty":"宋","verses":["月色半古寺，虫声杂疏钟。","江城缭山色，星斗摇空蒙。","徐行不自觉，徙倚树影中。","忽然变烟雨，江上东南风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-490f6b45-44d3-4dae-b66e-0000a7a298d7","tags":[]},{"id":"poem-7f6a3f2fe0efff2926027230","title":"别麻氏","author":"赵嘏","dynasty":"唐","verses":["晓哭呱呱动四隣，于君我作负心人。","出门便涉东西路，回首初惊枕席尘。","满眼泪珠和语咽，旧窗风月更谁亲。","分离况值花时节，从此东风不似春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-d96ab8f4-d899-42fc-a251-261b08c09eea","tags":[]},{"id":"poem-7f6ca5dfc5f972669d57af7d","title":"好事近·杨柳曲江头","author":"赵鼎","dynasty":"宋","verses":["杨柳曲江头，曾记彩舟良夕。","一枕楚台残梦，似行云无迹。","青山迢递水悠悠，何处问消息。","还是一年春暮，倚东风独立。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-960","tags":[]},{"id":"poem-7f6fbe3f2cd8c84ee0a085d2","title":"阮郎归·退红衫子乱蜂儿","author":"黄庭坚","dynasty":"宋","verses":["退红衫子乱蜂儿。","衣宽只为伊。","为伊去得忒多时。","教人直是疑。","长睡晚，理妆迟。","愁多懒画眉。","夜来算得有归期。","灯花则甚知。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-753","tags":[]},{"id":"poem-7f71c4431db8f810f8c9b888","title":"宴中山","author":"太宗皇帝","dynasty":"唐","verses":["驱马出辽阳，万里转旗常。","对敌六奇举，临戎八阵张。","斩鲸澄碧海，卷雾扫扶桑。","昔去兰萦翠，今来桂染芳。","云芝浮碎叶，冰镜上朝光。","回首长安道，方欢宴柏梁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-d7c51477-e08e-4f2e-ba3b-361807bbecea","tags":[]},{"id":"poem-7f74674069d4d8b38e99305f","title":"南乡子·二八花钿","author":"欧阳炯","dynasty":"五代","verses":["二八花钿，胸前如雪脸如莲。","耳坠金环穿瑟瑟，霞衣窄，笑倚江头招远客。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-4","tags":[]},{"id":"poem-7f7c7c6f4e3b4cb513345806","title":"题友生丛竹","author":"李咸用","dynasty":"唐","verses":["菊华寒露浓，兰愁晓霜重。","指佞不长生，蒲萐今无种。","安如植丛篁，他年待栖凤。","大则化龙骑，小可钓璜用。","留烟伴独醒，回阴冷闲梦。","何妨积雪凌，但为清风动。","乃知子猷心，不与常人共。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-787b7a62-4b3e-4010-b265-c5772c34dcba","tags":[]},{"id":"poem-7f7ce6970e3d58bbbb1e0f5e","title":"哭林艾轩","author":"陈俊卿","dynasty":"宋","verses":["出为岭峤澄清使，归作甘泉侍从臣。","百担有书行李重，千金无产橐中贫。","经旬把臂言犹在，昨日题诗墨尚新。","清晓访君呼不起，寝门一恸泪沾巾。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-bbf6e19d-8332-4c53-81c1-41e08dd9d919","tags":[]},{"id":"poem-7f7dfe0cd9292b46958b2a61","title":"如鱼水·轻霭浮空","author":"柳永","dynasty":"宋","verses":["轻霭浮空，乱峰倒影，潋滟十里银塘。","绕岸垂杨。","红楼朱阁相望。","芰荷香。","双双戏、㶉𫛶鸳鸯。","乍雨过、兰芷汀洲，望中依约似潇湘。","风淡淡，水茫茫。","动一片晴光。","画舫相将。","盈盈红粉清商。","紫薇郎。","修禊饮、且乐仙乡。","更归去，遍历銮坡凤沼，此景也难忘。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-185","tags":[]},{"id":"poem-7f86ab60578b2bb7f18fdcf6","title":"赋得李","author":"太宗皇帝","dynasty":"唐","verses":["玉衡流桂圃，成蹊正可寻。","鸎啼密叶外，蝶戏脆花心。","丽景光朝彩，轻霞散夕阴。","暂顾晖章侧，还眺灵山林。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-7cc40e68-b5bb-4af8-9a5b-5b6118881e86","tags":[]},{"id":"poem-7f878f5d2e9c889ca74f07b1","title":"送客游荆州","author":"李嘉祐","dynasty":"唐","verses":["草色随骢马，悠悠共出秦。","水传云梦晓，山接洞庭春。","帆影连三峡，猨声在四隣。","青门一分首，难见杜陵人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-1a3d9214-9963-48a6-bb04-ce3cb73e07b3","tags":["洞庭湖","送别"]},{"id":"poem-7f9270c7f28d5af1494af963","title":"枯椶","author":"杜甫","dynasty":"唐","verses":["蜀门多椶榈，高者十八九。","其皮割剥甚，虽众亦易朽。","徒布如云叶，青黄岁寒后。","交横集斧斤，凋丧先蒲柳。","伤时苦军乏，一物官尽取。","嗟尔江汉人，生成复何有。","有同枯椶木，使我沈叹久。","死者即已休，生者何自守。","啾啾黄雀啅，侧见寒蓬走。","念尔形影干，摧残没藜莠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-92c10ce9-23b4-4e64-9b20-fc62a84e288c","tags":[]},{"id":"poem-7f94b66678af1f7225cd99bd","title":"清平乐·别来春半","author":"李煜","dynasty":"五代","verses":["别来春半，触目柔肠断。","砌下落梅如雪乱，拂了一身还满。","雁来音信无凭，路遥归梦难成。","离恨恰如春草，更行更远还生。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-11","tags":[]},{"id":"poem-7f9c70d97471211c61485f9f","title":"杂诗三首 二","author":"沈佺期","dynasty":"唐","verses":["妾家临渭北，春梦著辽西。","何苦朝鲜郡，年年事鼓鼙。","燕来红壁语，莺向绿窗啼。","为许长相忆，阑干玉筯齐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-12e099e7-7474-41c3-a332-76035325ef81","tags":[]},{"id":"poem-7f9d19cc265fa51fdb64258e","title":"某敬采民言成六韵为安抚阁老尚书寿伏幸过目  其四","author":"张栻","dynasty":"宋","verses":["蜀江东下接襄江，总是当年蔽芾棠。","此地回旋莫嫌窄，且教春色满三湘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-8b4d34c1-51b0-4bbe-ae48-7559be196e9b","tags":[]},{"id":"poem-7fa009656d862520a18496c0","title":"江南词","author":"李益","dynasty":"唐","verses":["嫁得瞿塘贾，朝朝悮妾期。","早知潮有信，嫁与弄潮儿。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-9bd49546-5289-4351-97f4-d69296720dfc","tags":["闺怨","唐诗三百首","乐府"]},{"id":"poem-7fa755cae354deae1fea9d9c","title":"三十","author":"王梵志","dynasty":"唐","verses":["欲得儿孙孝，无过教及身。","一朝千度打，有罪更须嗔。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-ccd476fd-193d-4ddf-b089-0aad483a8164","tags":[]},{"id":"poem-7fb6403cc976febc66a5f52a","title":"郢州白雪楼（题拟）","author":"张休","dynasty":"唐","verses":["美人莫唱《阳春曲》，白尽湖南太守头。","（宋王之望《汉滨集》卷二《郢守乔民瞻寄襄阳雪中三绝因追述前过石城杯酒登临之胜为和》其三自注引。","）（王之望诗注云：「仆旧游白雪楼，见张休诗石刻，尾章云〖诗略〗。","今石已亡，民瞻询于老吏，遂得其全篇，云将复刻）（诸石。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-3cd355ba-c067-4e51-bccc-6f1c0ee7e2c9","tags":[]},{"id":"poem-7fb908a72d79b8ec024ee769","title":"鼓吹曲辞 君马黄","author":"李白","dynasty":"唐","verses":["君马黄，我马白。","马色虽不同，人心本无隔。","共作游冶盘，双行洛阳陌。","长劒既照曜，高冠何赩赫。","各有千金裘，俱为五侯客。","猛虎落陷穽，壮夫时屈厄。","相知在急难，独好亦何益。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-d4c03bc1-0596-4177-88ba-e42a97b0a7d9","tags":["知己","鼓吹曲辞","乐府"]},{"id":"poem-7fbd11eeab48c0aefe6e168c","title":"励学","author":"王建","dynasty":"唐","verses":["买地不肥实，其繁系耕凿。","良田少锄理，兰焦香亦薄。","勿以听者迷，故使宫征错。","谁言三岁童，还能分善恶。","孜孜日求益，犹恐业未博。","况我性顽蒙，复不勤修学。","有如朝暮食，暂亏忧陨获。","若使无六经，贤愚何所托。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-ab7653e1-0fe1-4051-bc3e-e6b08d29ae19","tags":[]},{"id":"poem-7fbd7e38cdaf12d745e58038","title":"仲子生日","author":"孙介","dynasty":"宋","verses":["寻常得子要佳晨，何幸生朝在仲春。","乐事赏心随处处，仁风和气似亲亲。","天恩有庇容团聚，家训无须旋卜邻。","杯酒献酬更祝颂，不须黄老拱星辰。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-cf92b4c1-452f-4a69-af66-56168e07e66d","tags":[]},{"id":"poem-7fbdbdd5c9abccafa04a62ac","title":"早秋贵溪南亭晚眺","author":"张祜","dynasty":"唐","verses":["溪流照槛肃埃氛，百里秋光草树分。","青壁峻时山背日，碧潭空处水销云。","千寻下彻鱼无隐，一点高飞鹭出群。","回首故乡人未去，乱蝉声噪不堪闻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-5e16814d-afb7-4b70-9a43-630e9b6be592","tags":[]},{"id":"poem-7fc02d1753f69c36aa80f830","title":"次韵陈右史赏醉落托","author":"释居简","dynasty":"宋","verses":["罗幙低开护曲阑，娇红落托醉扶难。","朝来嫩日疎云淡，纵有些风尽耐寒。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-121814aa-0eaf-4b63-8775-1e02d141ed71","tags":[]},{"id":"poem-7fc72ebd0a1939f6c0536a4f","title":"江村夜泊","author":"项斯","dynasty":"唐","verses":["日落江路黑，前村人语稀。","几家深树里，一火夜渔归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-f04c401f-69e1-476d-9e0c-c1d43e32c830","tags":[]},{"id":"poem-7fca867a140f2d76ede49e1e","title":"郊庙歌辞 梁郊祀乐章 庆休","author":"赵光逢、张衮","dynasty":"唐","verses":["大业来四夷，仁风和万国。","白日体无私，皇天辅有德。","七旬罪已服，六月师方克。","伟哉帝道隆，终始常作则。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-a4ed9fc0-2f60-4076-bdc6-10647b93bb3a","tags":[]},{"id":"poem-7fd2250076e438f44acd0c84","title":"隋帝陵下","author":"鲍溶","dynasty":"唐","verses":["白露沾衣隋主宫，云亭月馆楚淮东。","盘龙楼舰浮冤水，雕锦帆幢使乱风。","长夜应怜桀何罪，告成合笑禹无功。","伤心近似骊山路，陵树无根秋草中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-73021908-2c50-4e4d-bb43-a3081d3ffd90","tags":[]},{"id":"poem-7feb367b2b22bad5877152a1","title":"秋怀五首 三","author":"鲍溶","dynasty":"唐","verses":["九月夜如年，幽房劳别梦。","不知别日远，夜夜犹相送。","玉床暗虫响，锦席寒泪冻。","明镜失旧人，空林误归凤。","新年堪爱惜，锦字亦珍重。","一念皎皎时，幽襟非所用。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-f3a94c12-7462-4174-891e-4e1f01a80821","tags":[]},{"id":"poem-7fefc517b628cd2c16dd9aff","title":"章和二年中","author":"李贺","dynasty":"唐","verses":["云萧索，田风拂拂，麦芒如篲黍如粟。","关中父老百领襦，关东吏人乏诟租。","健犊春耕土膏黑，菖蒲丛丛沿水脉。","殷勤为我下田租，百钱携偿丝桐客。","游春漫光坞花白，野林散香神降席。","拜神得寿献天子，七星贯断姮娥死。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-246674af-83a0-456a-acf5-bb8aeeffba75","tags":[]},{"id":"poem-7ffe083d216393c3e4c6dfec","title":"奉使松府（伯三七七一。下同）","author":"胡皓","dynasty":"唐","verses":["蜀山固地险，（项云「固」当作「匝」，形近而讹。","）汉水接天平。","波涛去东别[一]，林嶂隐西倾[二]。","露白蓬根断，风秋草叶鸣。","孤舟忽不见，垂泪坐盈盈。","（[一]刘云：「东别谓大别也。","《禹贡》汉水又区为沧浪之水，至于大别。","」[二]刘云：「西倾谓西倾山。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-3650f2d2-92e2-4f0a-b138-eaf4aa2a068d","tags":[]},{"id":"poem-80001543710099625b7eb853","title":"南安夕阳山真寂寺题诗","author":"宣宗皇帝李忱","dynasty":"唐","verses":["惟爱禅林秋月空，谁能归去宿龙宫。","夜深闻法餐甘露，喜在莲花法界中。","（见明檇李陈懋仁撰《泉南杂志》卷上。","）（按陈懋仁，字无功，所著《泉南杂志》录唐人诗若干首，谓「《万首唐人绝句》中于吾郡及泉州有未收者，余录其诗于左。","如此备补遗。","」又原诗题注曰：「居邸时遁于此」，盖谓李忱曾遁居真寂寺也。","又诗末注曰：「见《泉州府志》」。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-6b0ae5b9-9af9-4ed8-9b3f-0d38d60c76f2","tags":[]},{"id":"poem-8001fd621750cba237115e3a","title":"赠别司空曙","author":"卢纶","dynasty":"唐","verses":["有月曾同赏，无秋不共悲。","如何与君别，又是菊花时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-dffd705d-29d2-422f-883a-36ae86876fce","tags":[]},{"id":"poem-800247b86cd70275aca72a6f","title":"鼓吹曲辞 战城南","author":"李白","dynasty":"唐","verses":["去年战桑干源，今年战葱河道。","洗兵条支海上波，放马天山雪中草。","万里长征战，三军尽衰老。","匈奴以杀戮为耕作，古来唯见白骨黄沙田。","秦家筑城备胡处，汉家还有烽火然。","烽火然不息，征战无已时。","野战格鬬死，败马号鸣向天悲。","乌鸢啄人肠，衔飞上挂枯树枝。","士卒涂草莽，将军空尔为。","乃知兵者是凶器，圣人不得已而用之。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-c0f1c8ed-bbf8-4ace-ac86-91e5e57d8ece","tags":["忧国忧民","战争","鼓吹曲辞","乐府","讽刺"]},{"id":"poem-8003646339e762cf928dca2c","title":"望九华寄池阳杜员外","author":"曹唐","dynasty":"唐","verses":["戴月早辞三秀馆，迟明初识九华峰。","差差玉劒寒铓利，褭褭青莲翠叶重。","奇状却疑人画出，岚光如为客添浓。","行春若到五溪上，此处褰帷正面逢。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-13227c7a-3367-4bdc-a362-094c8ff6e94b","tags":[]},{"id":"poem-80116f377247d60fa00d03e1","title":"赠特进汝阳王二十韵","author":"杜甫","dynasty":"唐","verses":["特进群公表，天人夙德升。","霜蹄千里骏，风翮九霄鹏。","服礼求毫发，惟忠忘寝兴。","圣情常有眷，朝退若无凭。","仙醴来浮蚁，奇毛或赐鹰。","清关尘不杂，中使日相乘。","晚节嬉游简，平居孝义称。","自多亲棣萼，谁敢问山陵。","学业醇儒富，辞华哲匠能。","笔飞鸾耸立，章罢凤骞腾。","精理通谈笑，忘形向友朋。","寸长堪缱绻，一诺岂骄矜。","已忝归曹植，何知对李膺。","招要恩屡至，崇重力难胜。","披雾初欢夕，高秋爽气澄。","尊罍临极浦，凫雁宿张灯。","花月穷游宴，炎天避郁蒸。","研寒金井水，檐动玉壶冰。","瓢饮唯三径，岩栖在百层。","且持蠡测海，况挹酒如渑。","鸿宝宁全秘，丹梯庶可凌。","淮王门有客，终不媿孙登。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-32e164a6-e25b-497c-993b-6a2f63e25daa","tags":["抒情","感激"]},{"id":"poem-8018e72a0aa15788b0e87927","title":"长安书事寄卢纶","author":"李端","dynasty":"唐","verses":["弱冠家庐岳，从师岁月深。","翻同老夫见，殊寡少年心。","及此时方晏，因之名亦沈。","趋途非要路，避事乐空林。","素业在山下，青泉当树阴。","交游有凋丧，离别代追寻。","向秀初闻笛，钟期久罢琴。","残愁犹满貌，余泪可沾襟。","勿以朱颜好，而忘白发侵。","终期入灵洞，相与炼黄金。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-017cc40c-e1e0-492e-9e35-f19cb643ad13","tags":[]},{"id":"poem-8021f25559172f39e02687f0","title":"调笑令","author":"杨景贤","dynasty":"元","verses":["师父，休妄想，那的是俺世尊强化出魔王将你心意降。","杜子春炼丹成虚诳，则为心不诚也有许多模样。","将一个小孩儿提起来石上撞，则一惊那金丹忒楞化粉蝶儿飞扬。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3401","tags":[]},{"id":"poem-802dd2119c0315b26f560ac9","title":"营州歌","author":"高适","dynasty":"唐","verses":["营州少年厌原野，狐裘蒙茸猎城下。","虏酒千钟不醉人，胡儿十岁能骑马。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-d43a140a-9152-4bbf-8d94-7254f913f969","tags":["生活","边塞"]},{"id":"poem-803ab7b16e7a0a3d652fa3f3","title":"五供养","author":"刘唐卿《白兔记》","dynasty":"元","verses":["十中缺九，喜姑姑产下穷刘。","儿夫曾嘱付。","怎干休？把花言觅诱，倘说得儿入手，管交一命丧清流。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8932","tags":[]},{"id":"poem-803f1c5202b4cbe7fc318636","title":"恋情深·玉殿春浓花烂熳","author":"毛文锡","dynasty":"五代","verses":["玉殿春浓花烂熳，族神仙伴。","罗裙窣地缕黄金，奏清音。","酒阑歌罢两沉沉，一笑动君心。","永作鸳鸯伴，恋情深。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-27","tags":[]},{"id":"poem-804b0a18b93e3ba52c3fe528","title":"无衣","author":"佚名","dynasty":"先秦","verses":["岂曰无衣七兮？不如子之衣，安且吉兮！","岂曰无衣六兮？不如子之衣，安且燠兮！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-121","tags":[]},{"id":"poem-804c383ce9ccbd2bdf6aa37c","title":"赵正之宠贶和篇褒与过厚适传新命念暌违之有日预深怅然辄次其韵","author":"李纲","dynasty":"宋","verses":["七言八法定谁师，妙处工夫只自知。","南浦西山久同赏，清风明月更相思。","瓌材卓荦承恩日，衰病侵寻念去时。","垂老相看重言别，莫辞潋滟十分巵。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-db0949c4-4563-42f7-bbe7-004ef5ad96db","tags":[]},{"id":"poem-80504c593aaec8c29e77e48c","title":"后庭花","author":"萧德祥《小孙屠》","dynasty":"元","verses":["教奴怨恨你，魂灵儿无所归。","冤枉难伸诉，苍天不可期。","你不与，外人知。","施呈巧计。","使这般狼儿识，眼将咱一命倾。","(又唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8670","tags":[]},{"id":"poem-8054695dd242303af7986faf","title":"送客赋得巴江夜猿","author":"李端","dynasty":"唐","verses":["巴水天边路，啼猿伤客情。","迟迟云外尽，杳杳树中生。","残月暗将落，空霜寒欲明。","楚人皆掩泪，闻到第三声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-06a0a6ef-06f6-45dc-b9be-c94b65e8c7e5","tags":[]},{"id":"poem-805cc0362116cf898f96b548","title":"雁门太守行","author":"李贺","dynasty":"唐","verses":["黑云压城城欲摧，甲光向日金鳞开。","角声满天秋色里，塞上燕脂凝夜紫。","半卷红旗临易水，霜重鼓寒声不起。","报君黄金台上意，提携玉龙为君死。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-5ec77a99-b8d7-4845-b03e-47704d8f4fd9","tags":["战争","初中古诗","乐府","九年级下册(课外)","边塞","拟古"]},{"id":"poem-8069b7b97ef2735f316377fb","title":"西施","author":"苏拯","dynasty":"唐","verses":["吴王从骄佚，天产西施出。","岂徒伐一人，所希救群物。","良由上天意，恶盈戒奢侈。","不独破吴国，不独生越水。","在周名襃姒，在纣名妲己。","变化本多涂，生杀亦如此。","君王政不修，立地生西子。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-c8621171-5488-4eec-9716-861c79c1df63","tags":[]},{"id":"poem-806d7ee432cb336d092b19ce","title":"送至洪沙弥游越","author":"皎然","dynasty":"唐","verses":["知尔学无生，不应伤此别。","相逢宿我寺，独往游灵越。","早晚花会中，经行剡山月。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-47837c8d-2791-4ba9-bb56-3080ef8e8b43","tags":[]},{"id":"poem-8071f9a07fe6337d4e0b4394","title":"琵琶","author":"太宗皇帝","dynasty":"唐","verses":["半月无双影，全花有四时。","摧藏千里态，掩抑几重悲。","促节萦红袖，清音满翠帷。","驶弹风响急，缓曲钏声迟。","空余关陇恨，因此代相思。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-c5629da4-989d-4af5-a5e8-db1a6aaa8e6f","tags":[]},{"id":"poem-80728f1c78deb4cd33c98d48","title":"题涧饮寺","author":"李涉","dynasty":"唐","verses":["百年如梦竟何成，白发重来此地行。","还似萧郎许玄度，再看庭石悟前生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-33a209ae-7252-42fe-b235-01d6086e64f6","tags":[]},{"id":"poem-80774df92102f6edac14d976","title":"和梁签判颍州西湖十三题 西湖","author":"苏颂","dynasty":"宋","verses":["椒泽疏源势不休，绕城冰玉湛寒流。","凫鹥容与菰蒲乱，占得江湖一望秋。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-aabcacee-860f-4dd4-b1ce-08b813ed6c19","tags":["西湖"]},{"id":"poem-807e1019eb1f8819580d4478","title":"酬当涂何户曹畏斋金陵三篇见寄兼柬饷台上幕许从道  其二","author":"释居简","dynasty":"宋","verses":["笔耕白首不逢年，间得新题似得仙。","磨透铁泓空费力，吟残金薤弗成篇。","未忘陋巷希瞠若，不信长虹死浩然。","小驻行云聊寄恨，莫为愁雨湿吴天。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-ff89e45b-7596-4497-a32f-966b3b7dece9","tags":[]},{"id":"poem-807fe9199a75f4752dc929ec","title":"闻赤松舒道士下世","author":"贯休","dynasty":"唐","verses":["地变贤人丧，疮痍不可观。","一闻消息苦，千种破除难。","阴骘那虚掷，深山近始安。","玄关评兔角，玉器琢鸡冠。","傲野高难狎，融怡美不殚。","冀迎新渥泽，遽逐逝波澜。","蜕壳埋金隧，飞精驾锦鸾。","倾摧千仞壁，枯歇一株兰。","仙庙诗虽继，苔墙篆必鞔。","烟霞成片黯，松桂著行干。","影拄溪流咽，堂扃隟月寒。","寂寥遗药犬，缥缈想琼竿。","伊昔相寻远，留连几尽欢。","论诗花作席，炙菌叶为盘。","彭伉心相似，承祯趣一般。","琴弹溪月侧，棋次砌云残。","儵忽成千古，飘零见百端。","荆囊春浩浩，吴越浪漫漫。","已矣红霞子，空留白石坛。","无弦亦须绝，回首一长叹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-df764d09-6970-4b94-ab8d-1bf5cc159c79","tags":[]},{"id":"poem-808992ab63eb08c2a03649d3","title":"秋怀赤松道士","author":"贯休","dynasty":"唐","verses":["仙观在云端，相思星斗寒。","常怜呼鹤易，却恨见君难。","石罅青虵湿，风榸白菌干。","终期花月下，坛上听君弹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-2e4e8c4e-9f12-407c-8ad7-055d61527087","tags":[]},{"id":"poem-8090a7003d8888878ae6a636","title":"十无诗寄桂府杨中丞 三","author":"赵嘏","dynasty":"唐","verses":["遥闻桂水遶城隅，城上江山满画图。","为问訾家洲畔月，清秋拟许醉狂无。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-fdfbac87-6a5c-42cb-8fab-98bae5fe4c07","tags":[]},{"id":"poem-80c00465029c5a7adaead699","title":"题刘相公光德里新搆茅亭","author":"李洞","dynasty":"唐","verses":["野色迷亭晓，龙墀待押班。","带涎移海木，兼雪写湖山。","月白吟床冷，河清直印闲。","唐封三万里，人偃翠微间。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-dff982ae-5bd7-437a-868d-02accbf13d5f","tags":[]},{"id":"poem-80c92bda5d677c04ae91958b","title":"秋蛩","author":"雍裕之","dynasty":"唐","verses":["雨绝苍苔地，月斜青草阶。","蛩鸣谁不怨，况是正离怀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-c806c9c2-8095-46bc-9eb7-af8135598f2a","tags":[]},{"id":"poem-80ccc12cda4f6986b52f35b0","title":"郊庙歌辞 封泰山乐章 豫和 二","author":"张说","dynasty":"唐","verses":["亿上帝，临下庭。","骑日月，陪列星。","嘉祝信，大糦馨。","澹神心，醉皇灵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-4902d495-3ed3-4aa2-9c67-36a054455042","tags":["泰山"]},{"id":"poem-80d09b8657bd39402c13ee29","title":"送僧鸾归蜀宁亲","author":"张乔","dynasty":"唐","verses":["歌诗精外学，天子是知音。","坐夏宫钟近，宁亲劒阁深。","高名彻西国，旧迹寄东林。","自此栖禅者，因师满蜀今。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-96aca1e5-a4e2-4ff0-855d-48732f37b359","tags":[]},{"id":"poem-80d2fa2ad62ce755393ae7f8","title":"菩萨蛮·娟娟明月如霜白","author":"向子𬤇","dynasty":"宋","verses":["娟娟明月如霜白。","鳌山可是蓬山隔。","恨不及春风。","行云处处同。","暖香红雾里。","一笑谁新喜。","知得远愁无。","春衫有泪珠。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-770","tags":[]},{"id":"poem-80dc35d68277f75c6ac6107a","title":"塞垣春·暮色分平野","author":"周邦彦","dynasty":"宋","verses":["暮色分平野。","傍苇岸、征帆卸。","烟村极浦，树藏孤馆，秋景如画。","渐别离气味难禁也。","更物象、供潇洒。","念多材浑衰减，一怀幽恨难写。","追念绮窗人，天然自、风韵娴雅。","竟夕起相思，谩嗟怨遥夜。","又还将、两袖珠泪，沈吟向寂寥寒灯下。","玉骨为多感，瘦来无一把。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-411","tags":[]},{"id":"poem-80f6317a41c5cc6fe8c6e6b0","title":"饯别王十一南游","author":"刘长卿","dynasty":"唐","verses":["望君烟水阔，挥手泪沾巾。","飞鸟没何处，青山空向人。","长江一帆远，落日五湖春。","谁见汀洲上，相思愁白苹。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-1487452b-5f49-4f4f-9913-1f3ec1cddf95","tags":["唐诗三百首","长江","友情","送别","五言律诗"]},{"id":"poem-80f8ce205efed108f34a668c","title":"送别","author":"王维","dynasty":"唐","verses":["下马饮君酒，问君何所之。","君言不得意，归卧南山陲。","但去莫复问，白云无尽时。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-31cc87f3-da0f-421d-8674-8753530077e2","tags":["唐诗三百首","抒情","写景","友情","送别"]},{"id":"poem-80fb155ac7162351c230b1d8","title":"敦煌廿咏（并序） 十六、贺拔堂咏","author":"敦煌人作品[一]","dynasty":"唐","verses":["英雄传贺拔，割据王[三二]敦煌。","五郡征般匠，千金造寝堂。","绮檐安兽瓦，粉壁架鸿[三三]梁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-11dddae7-85fc-491c-8a2f-7cb4ef7c736a","tags":[]},{"id":"poem-80fe3889f858a57ea517c796","title":"望吾乡","author":"无名氏《张协状元》","dynasty":"元","verses":["家住西川，回首泪暗垂。","中途怎知人劫去，娶它贫女是不得已。","幸然脱此处，都城在，眼下里，尽总是繁华地。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2597","tags":[]},{"id":"poem-810495cd67e0b4fccb5a2556","title":"都梁十景诗 清风山闻笛","author":"米芾","dynasty":"宋","verses":["铁笛谁吹一曲哀，清风约我上层台。","悠扬正到堪听处，怕惹闲愁却下来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-73472cbc-2243-43f6-919f-52044e1ef438","tags":[]},{"id":"poem-8110654245dd52d78ca24bbb","title":"送欧阳衮归闽中","author":"项斯","dynasty":"唐","verses":["秦城几年住，犹著故乡衣。","失意时相识，成名后独归。","海秋蛮树黑，岭夜瘴禽飞。","为学心难满，知君更掩扉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-e6f8831f-8a6e-489a-b3c5-7a47faaaa98b","tags":[]},{"id":"poem-811acc21ec32f3a625ce5988","title":"春日","author":"朱熹","dynasty":"宋","verses":["胜日寻芳泗水滨，无边光景一时新。","等闲识得东风面，万紫千红总是春。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-春日","tags":[]},{"id":"poem-811e9c70edb7c650515434ce","title":"寄白学士","author":"张籍","dynasty":"唐","verses":["自掌天书见客稀，纵因休沐锁双扉。","几回扶病欲相访，知向禁中归未归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-5951cc09-83ca-4e54-83dd-97bedbce2d78","tags":[]},{"id":"poem-81201730a8cbf96c19c59e3e","title":"兵要望江南 马药方第三十（四首） 三","author":"易静","dynasty":"唐","verses":["鼻上赤，二十岁无零。","马鼻若青三十岁，公字虽（辛本作「须」）当念五乘，此象最（辛本作「甚」）分明。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-ad8ed22d-69ba-48ae-bf84-006d15394f1f","tags":[]},{"id":"poem-8127282834d8a3ab16b06356","title":"归田乐·春又去","author":"晁补之","dynasty":"宋","verses":["春又去，似别佳人幽恨积。","闲庭院，翠阴满，添昼寂。","一枝梅最好，至今忆。","正梦断，炉烟袅，参差疏帘隔。","为何事、年年春恨，问花应会得。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-137","tags":[]},{"id":"poem-81330d09d7ff3670c2769b0d","title":"偈颂七十一首  其三○","author":"释了惠","dynasty":"宋","verses":["旧岁已去，去不可追。","新岁当来，来不可拒。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-77340ed0-218a-44aa-b5e2-fb5d98ca157c","tags":[]},{"id":"poem-81338fdc2bfe97e56a091b9e","title":"浣溪沙·倾国倾城恨有余","author":"薛昭蕴","dynasty":"五代","verses":["倾国倾城恨有余，几多红泪泣姑苏，倚风凝睇雪肌肤。","吴主山河空落日，越王宫殿半平芜，藕花菱蔓满重湖。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-32","tags":[]},{"id":"poem-8139ab87a74bd97c92766c08","title":"茉莉花二首  其二","author":"李纲","dynasty":"宋","verses":["风露扶疏蔓翠藤，玉花剪刻见层层。","清香夜久偏闻处，寂寞书生对一灯。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-e9927371-3349-498a-b8f2-9a9f02ab9226","tags":[]},{"id":"poem-81429b1788773eae495868b9","title":"和渊眀拟古九首  其二","author":"李纲","dynasty":"宋","verses":["惊心如伤禽，衰质若凋柳。","百年能几时，处世安得久。","寤寐若有失，哀我泉下友。","平生不识面，况复衘杯酒。","知心乃如斯，此意岂可负。","管鲍贫时交，于古亦云厚。","范张久已亡，今人那复有。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-05261232-f79a-41bb-9d5c-7b800878d381","tags":[]},{"id":"poem-81461a37788dd54c93220ba2","title":"内家娇·煦景朝升","author":"柳永","dynasty":"宋","verses":["煦景朝升，烟光昼敛，疏雨夜来新霁。","垂杨艳杏，丝软霞轻，绣出芳郊明媚。","处处踏青斗草，人人眷红偎翠。","奈少年、自有新愁旧恨，消遣无计。","帝里。","风光当此际。","正好恁携佳丽。","阻归程迢递。","奈好景难留，旧欢顿弃。","早是伤春情绪，那堪困人天气。","但赢得、独立高原，断魂一饷凝睇。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-128","tags":[]},{"id":"poem-8149057a7c75ea3ec4712c26","title":"松寺","author":"卢延让","dynasty":"唐","verses":["山寺取凉当夏夜，共僧蹲坐石堦前。","两三条电欲为雨，七八个星犹在天。","衣汗稍停床上扇，茶香时拨涧中泉。","通宵听论莲华义，不藉松窗一觉眠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-c9c61b9a-b463-43e2-b6cd-b50deb767676","tags":[]},{"id":"poem-814f3dbbaf78cf1bf438dd08","title":"寄崔纯亮","author":"孟郊","dynasty":"唐","verses":["百川有余水，大海无满波。","器量各相悬，贤愚不同科。","群辩有姿语，众欢无行歌。","唯余洛阳子，郁郁恨常多。","时读过秦篇，为君涕滂沱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-4dd4e413-e9fd-4afc-9c55-fff3ee1a86d3","tags":[]},{"id":"poem-8150bca41120091101b2e8cc","title":"夏日东斋","author":"曹松","dynasty":"唐","verses":["三庚到秋伏，偶来松槛立。","热少清风多，开门放山入。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-2d614385-94d5-4f15-b763-f186f2c39b8f","tags":[]},{"id":"poem-8158567adc71dbc0d7d1e806","title":"荔枝香·甚处寻芳赏翠","author":"柳永","dynasty":"宋","verses":["甚处寻芳赏翠，归去晚。","缓步罗袜生尘，来绕琼筵看。","金缕霞衣轻褪，似觉春游倦。","遥认，众里盈盈好身段。","拟回首，又伫立、帘帏畔。","素脸红眉，时揭盖头微见。","笑整金翘，一点芳心在娇眼。","王孙空恁肠断。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-122","tags":[]},{"id":"poem-815bda88b0cc02ddb2642405","title":"杂诗 十三","author":"无名氏","dynasty":"唐","verses":["近寒食雨草萋萋，著麦苗风柳映堤。","早是有家归未得，杜鹃休向耳边啼。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-31e9a6b0-5035-4b1b-a9d3-ff1c279f53b6","tags":["唐诗三百首","寒食节","七言绝句","思乡","感伤"]},{"id":"poem-8178d888ccf8816c74398ef1","title":"和彭进士秋日游靖居山寺","author":"李咸用","dynasty":"唐","verses":["秋山入望已无尘，况得闲游谢事频。","问著尽能言祖祖，见时应不是真真。","添瓶野水遮还急，伴塔幽花落又新。","自笑未曾同逸步，终非宗炳社中人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-e6587eda-dc75-4044-b031-3126116ac0f6","tags":[]},{"id":"poem-818261e4666a1c109d8a6c6c","title":"送士濂弟之京","author":"慧忠","dynasty":"唐","verses":["行色翩翩入帝都，壮怀此去莫踌躇。","昔曾故国登高第，今向新朝再上书。","汝负才猷堪济世，我惭衰朽合闲居。","[鸰]（鸽）原今日常相望，衣锦还乡常有余。","（见光绪廿六年刊翁昭泰纂《浦城县志》卷三九引《章氏会谱》。","）（按：题下原注：「士濂，得象祖。","」宋祁《景文集》卷五九《文宪章公墓志铭》：「曾祖仁嵩，仕李昪为驾部郎中。","……祖士廉，汀州宁化令。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-cbb70885-32ee-423f-8216-f92f151fa1e7","tags":[]},{"id":"poem-818462bf5a9761ca97429250","title":"颂古七十六首  其七四","author":"释士珪","dynasty":"宋","verses":["杨歧老人锁口诀，万里长城一条铁。","斫牌禅客知到来，不动金锤脑门裂。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-5dab0133-4551-490e-b8d7-4842accf09a0","tags":[]},{"id":"poem-818abeb80e765643b56cd622","title":"郊庙歌辞 祭汾阴乐章 顺和","author":"源光裕","dynasty":"唐","verses":["方丘既膳，嘉飨载谧。","齐敬毕诚，陶匏贵质。","秀毕丰荐，芳俎盈实。","永永福流，其升如日。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-f7ba4362-047b-40e8-8a43-17e6a1d93ca2","tags":[]},{"id":"poem-818ada88125ef9d1d057035c","title":"疏影·苔枝缀玉","author":"姜夔","dynasty":"宋","verses":["苔枝缀玉。","有翠禽小小，枝上同宿。","客里相逢，篱角黄昏，无言自倚修竹。","昭君不惯胡沙远，但暗忆、江南江北。","想佩环、月夜归来，化作此花幽独。","犹记深宫旧事，那人正睡里，飞近蛾绿。","莫似春风，不管盈盈，早与安排金屋。","还教一片随波去，又却怨、玉龙哀曲。","等恁时、重觅幽香，已入小窗横幅。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-136","tags":["宋词三百首"]},{"id":"poem-81943f1fce391da9e40eca8b","title":"临江仙·高咏楚词酬午日","author":"陈与义","dynasty":"宋","verses":["高咏楚词酬午日，天涯节序匆匆。","榴花不似舞裙红。","无人知此意，歌罢满帘风。","万事一身伤老矣，戌葵凝笑墙东。","酒杯深浅去年同。","试浇桥下水，今夕到湘中。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-112","tags":["宋词三百首"]},{"id":"poem-81acb2612c39e43b380b3313","title":"句  其一","author":"赵崇嶓","dynasty":"宋","verses":["苑墙当北斗，宫树近朝阳。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-241a7b9a-1ec7-4251-930b-74f8e603a9d4","tags":[]},{"id":"poem-81b593c7d4c1fca468430950","title":"尾","author":"杨景贤","dynasty":"元","verses":["告世尊肯发慈悲力，我着唐三藏西游便回。","那唐僧，火孩儿妖怪放生了他，到前面须得二圣郎救了你。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-10337","tags":[]},{"id":"poem-81b8c292b876b252764a5588","title":"寄舒州杜员外","author":"徐铉","dynasty":"宋","verses":["信到得君书，知君已下车。","粉闱情在否，莲幕兴何如。","人望征贤入，余思从子居。","灊山真隠地，凭为卜茅庐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-e4ff3b2e-4ee0-4fed-8f7b-ba5ca1e46c86","tags":[]},{"id":"poem-81b954d41b80789f299e7194","title":"梦江南·兰烬落","author":"皇甫松","dynasty":"唐","verses":["兰烬落，屏上暗红蕉。","闲梦江南梅熟日，夜船吹笛雨萧萧，人语驿边桥。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-24","tags":[]},{"id":"poem-81ca9206da7a97b8daf0ad64","title":"次韵赠新笋","author":"王十朋","dynasty":"宋","verses":["候届中和日渐长，箨龙忽到爱松堂。","便惊诗句含蔬味，更觉庖厨有细香。","未学坡公参玉板，且同韩子赋筼筜。","笋来茶往非为礼，端为诗情故得尝。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-2e982d6f-a7a4-406a-b3b8-10460d12a068","tags":[]},{"id":"poem-81d0e17997fe5185bcd84ef6","title":"代陈季若上张帅  其四","author":"林光朝","dynasty":"宋","verses":["长陪彩仗下蓬莱，万岁声中霁色开。","自是北门须卧护，双旌迢递日边来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-3f6dba4d-153d-442b-aed7-fd5512ca5c49","tags":[]},{"id":"poem-81d994caa36216ffef8b271b","title":"过钱塘","author":"释居简","dynasty":"宋","verses":["初日驱阴积翳销，鹳鵞嘈杂橹初摇。","白鸥踏浪平如地，不似吴儿学弄潮。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-2ae5dab6-1a31-4996-99dd-6680cfa2b528","tags":[]},{"id":"poem-81e276b2dcede1e096b785cd","title":"巢乌行","author":"鲍溶","dynasty":"唐","verses":["乌生几子林萧条，雄乌求食雌守巢。","夜愁风雨巢倾覆，常见一乌巢下宿。","日长雏饥雄未回，雌鸟下巢去哀哀。","野田春尽少遗谷，寻食不得饥飞来。","黄雀亦引数青雀，雀飞未远乌惊落。","既分青雀噉尔雏，尔雏虽长心何如。","将飞不飞犹未忍，古瑟写哀哀不尽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-4dfd87b6-3a34-4abd-bfea-b32c46479f15","tags":[]},{"id":"poem-81f02b46a5c8ca3299bdb0f2","title":"依韵赠南安方处士五首 一","author":"徐夤","dynasty":"唐","verses":["七贵五侯生肯退，利尘名网死当抛。","黔娄寂寞严陵卧，借问何人与结交。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-2b534e5f-fc54-4244-b89b-1d2146c2da67","tags":[]},{"id":"poem-81fa49224c9e2aede91e037a","title":"酬丘拱外甥览余旧文见寄","author":"李端","dynasty":"唐","verses":["丘迟本才子，始冠即周旋。","舅乏郄鉴爱，君如衞玠贤。","礼将金友等，情向玉人偏。","鄙俗那劳似，龙钟却要怜。","投甎聊取笑，赠绮一何妍。","野坐临黄菊，溪行踏绿钱。","岩高云反下，洞黑水潜穿。","僻岭猿偷栗，枯池雁唼莲。","身居霞外寺，思发月明田。","犹恨萦尘网，昏昏过几年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-a76e84bc-e1e1-459a-90bb-e2185b4a4ba3","tags":[]},{"id":"poem-82017735043fd0f9ddf88f14","title":"废宅","author":"周𣸣","dynasty":"宋","verses":["牢落画堂空锁尘，荒凉庭树暗消春。","豪家莫笑此中事，曾见此中人笑人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-7c5c27c2-da30-4c45-ad91-c74c5e22eae5","tags":[]},{"id":"poem-820f04083c92dec788a9b00a","title":"效赵学士体成口号十章献开府太师  其六","author":"司马光","dynasty":"宋","verses":["过春稀复到诸园，厌苦终朝鼓吹喧。","招得老僧江外至，啜茶挥麈话松轩。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-b59d6182-af1e-41de-9401-1bc1fe260eb7","tags":[]},{"id":"poem-8213e929190b7df7d65d81cb","title":"上俞许二判官","author":"贯休","dynasty":"唐","verses":["近抛蓑笠者，急善遇休明。","未省亲宗伯，焉能识正声。","病容经夏在，岳梦入秋幷。","无限林中意，今逢许郭倾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-1f4b7a50-1c95-49ae-8f30-c57dc39bda98","tags":[]},{"id":"poem-82161b5dd27a9245bf138b05","title":"渔家傲·五月榴花妖艳烘","author":"欧阳修","dynasty":"宋","verses":["五月榴花妖艳烘。","绿杨带雨垂垂重。","五色新丝缠角粽。","金盘送。","生绡画扇盘双凤。","正是浴兰时节动。","菖蒲酒美清尊共。","叶里黄骊时一弄。","犹瞢忪。","等闲惊破纱窗梦。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-699","tags":[]},{"id":"poem-82298b4a1b33547fc7aa7e4b","title":"记征人语","author":"纳兰性德","dynasty":"清","verses":["边月无端照别离，故园何处寄相思。","西风不解征人语，一夕萧萧满大旗。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-235","tags":[]},{"id":"poem-822a2679d2494fa7fe2b763f","title":"回波辞","author":"李景伯","dynasty":"唐","verses":["回波尔时酒巵，微臣职在箴规。","侍䜩既过三爵，喧哗窃恐非仪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-b35fe792-9512-408f-a45b-3fb4bcd4f89c","tags":[]},{"id":"poem-822bab525d4d3cb84051f8ce","title":"江南旅情","author":"祖咏","dynasty":"唐","verses":["楚山不可极，归路但萧条。","海色晴看雨，江声夜听潮。","剑留南斗近，书寄北风遥。","为报空潭橘，无媒寄洛桥。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-江南旅情","tags":[]},{"id":"poem-823cbef922ae55cc592c2dfb","title":"谢叶文昌二首  其一","author":"释居简","dynasty":"宋","verses":["星履声中识典刑，洗空浮俗快双明。","四朝孰愈德耆艾，九鼎曷如身重轻。","只作寻常高步武，安知咫尺是钧衡。","冲和一点关埏埴，噫欠春风六合生。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-dcdce3f4-fc8c-4781-97db-9fa4730c2df0","tags":[]},{"id":"poem-8241d8dabd9cb41af21bd951","title":"送崔琦赴宣州幕","author":"卢纶","dynasty":"唐","verses":["五马临流待幕宾，羡君谈笑出风尘。","身闲就养宁辞远，世难移家莫厌贫。","天际晓山三峡路，津头腊市九江人。","何处遥知最惆怅，满湖青草鴈声春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-6d8d65c5-372c-4d4d-afae-5ada1d1ff2c7","tags":[]},{"id":"poem-825190210c4b9922623b524c","title":"送朱大游塞","author":"张南史","dynasty":"唐","verses":["岁暮一为别，江湖聊自宽。","且无人事处，谁谓客行难。","郢曲怜公子，吴州忆伯鸾。","苍苍远山际，松柏独宜寒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-d5f86b06-3568-4bf7-95ac-7ca3e383b074","tags":[]},{"id":"poem-825c6836f1dab9a5eeb7e56e","title":"颂古三十一首  其二二","author":"释安永","dynasty":"宋","verses":["入草亲寻草里人，重重有路掌中平。","不遇大商空突晓，日高犹听打三更。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-f48590ce-ea86-48d3-9c03-ce6c00c8693c","tags":[]},{"id":"poem-82606ffd06f90505bf0257ac","title":"秋晚度废关","author":"李行言","dynasty":"唐","verses":["秦郊平旧险，周德眷遗黎。","始闻清夜柝，俄见落封泥。","物色来无限，津途去不迷。","空亭谁问马，闲戍但鸣鸡。","山月寒弥净，河风晓更凄。","赠言杨伯起，非复是关西。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-f3fcece0-91c8-4695-8811-df33ba834138","tags":[]},{"id":"poem-8269e1306dc586d77865f56f","title":"头陀岭无相院","author":"陈岩","dynasty":"宋","verses":["头陀岭下招提境，画阁阑干几度凭。","游客骤来还倏去，看山输与在家僧。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-e5d4d34a-eb8f-49e8-b891-c374d2d1ef60","tags":[]},{"id":"poem-826ed1c6bc92486747d46ff6","title":"句  其二","author":"刘洞","dynasty":"宋","verses":["翻忆潘郎章奏内，阴阴日暮好沾巾。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-9bf350ce-f260-471b-8242-10390fd3fe57","tags":[]},{"id":"poem-8270fc43feea14787cd388b1","title":"含笑花五首  其三","author":"李纲","dynasty":"宋","verses":["窜逐流离老病身，天涯相见意相亲。","粲然不用干金买，应记当年作赋人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-09086f6d-6d59-4008-942b-611467e69fcb","tags":[]},{"id":"poem-8271fa2edb105d1dd109ec43","title":"天门山","author":"余芑舒","dynasty":"宋","verses":["谁将嘉号标奇观，山鸟山花第一重。","天阙常时瞻北极，县图此处数西峰。","景云百战犹遗址，当日诸公几瘦筇。","定有英灵来访旧，夜闻嘶马晓无踪。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-edf4bb95-0259-409f-95b7-3f0207795f4f","tags":["天门山"]},{"id":"poem-82794d71e94c221e8b081e45","title":"满路花・促拍满路花·金花落烬灯","author":"周邦彦","dynasty":"宋","verses":["金花落烬灯，银砾鸣窗雪。","夜深微漏断，行人绝。","风扉不定，竹圃琅玕折。","玉人新间阔。","著甚情悰，更当恁地时节。","无言敧枕，帐底流清血。","愁如春后絮，来相接。","知他那里，争信人心切。","除共天公说。","不成也还，似伊无个分别。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-426","tags":[]},{"id":"poem-82836da3e1d634c8f8e172ad","title":"寄姪","author":"胡舜陟","dynasty":"宋","verses":["东辅书初至，西宫夜正寒。","感时嗟阻阔，喜汝报平安。","学耨知兼力，辞淳发巨澜。","三冬文史足，轩翥未应难。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-6c15dd60-6b33-4911-9a98-44f8996ea0b7","tags":[]},{"id":"poem-8283fb691870562d5c6424d5","title":"师亲写版牌云 二","author":"义存","dynasty":"唐","verses":["欲得不招无间业，莫谤如来正法轮。","有物密救人，争奈人不知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-f2e0e08a-25e8-414a-a241-dab851dba13e","tags":[]},{"id":"poem-8286b9866618333ca0b726bc","title":"满庭芳·玉鼎翻香","author":"蔡伸","dynasty":"宋","verses":["玉鼎翻香，红炉叠胜，绮窗疏雨潇潇。","故人相过，情话款良宵。","酒晕微红衬脸，横波浸、满眼春娇。","云屏掩，鸳鸯被暖，敧枕听寒潮。","如今，成别恨，临风对月，总是无聊。","念伤心南陌，执手河桥。","还似一声春梦，离魂断、楚些难招。","佳期在，踏青时候，花底听鸣镳。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-924","tags":[]},{"id":"poem-82948ca249fcf2617d4eb606","title":"九歌·国殇","author":"屈原","dynasty":"先秦","verses":["操吴戈兮被犀甲，车错毂兮短兵接。","旌蔽日兮敌若云，矢交坠兮士争先。","凌余阵兮躐余行，左骖殪兮右刃伤。","霾两轮兮絷四马，援玉枹兮击鸣鼓。","天时怼兮威灵怒，严杀尽兮弃原野。","出不入兮往不反，平原忽兮路超远。","带长剑兮挟秦弓，首身离兮心不惩。","诚既勇兮又以武，终刚强兮不可凌。","身既死兮神以灵，魂魄毅兮为鬼雄。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-10","tags":[]},{"id":"poem-82a6872ef33c1d5ae86ad284","title":"送封太守","author":"王维","dynasty":"唐","verses":["忽解羊头削，聊驰熊首轓。","扬舲发夏口，按节向吴门。","帆暎丹阳郭，枫攒赤岸村。","百村多候吏，露冕一何尊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-684f6b6f-c85c-4f04-968e-2b7beefae631","tags":[]},{"id":"poem-82a8a577acf8f81965e35204","title":"江村行","author":"张籍","dynasty":"唐","verses":["南塘水深芦笋齐，下田种稻不作畦。","耕场磷磷在水底，短衣半染芦中泥。","田头刈莎结为屋，归来系牛还独宿。","水淹手足尽有疮，山蝱遶身飞飏飏。","桑林椹黑蚕再眠，妇姑采桑不向田。","江南热旱天气毒，雨中移秧颜色鲜。","一年耕种长苦辛，田熟家家将赛神。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-667d82a0-09a4-4191-966a-ab32956894f5","tags":[]},{"id":"poem-82cbd619d0da7c5ba2f3101b","title":"峡口送友人","author":"司空曙","dynasty":"唐","verses":["峡口花飞欲尽春，天涯去住泪沾巾。","来时万里同为客，今日飜成送故人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-ddf96d5e-ba4c-4bbc-9630-f4cc54d871a5","tags":["离别","春天"]},{"id":"poem-82cc96fa3b902f8e42de676a","title":"再用才子富文华校雠天禄阁韵赠周教授  其七","author":"陈造","dynasty":"宋","verses":["审知才非充，敢怨言不雠。","进乃隔九虎，退且办十牛。","向非食不足，此檄当径投。","黄馘渔樵翁，揣分吾其俦。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-37454649-bcc2-4bab-8429-8d5e0e41bf82","tags":[]},{"id":"poem-82d207ee2182a8ab528773b0","title":"暮春杂咏八首  其二","author":"曾协","dynasty":"宋","verses":["莲沼琼瑶堕，萱庭锦绣张。","静闻人语好，闲爱水风凉。","藜杖休行乐，蒲团且坐忘。","沙禽相识惯，趯趯近胡床。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-693ed87d-862c-4b95-9214-eab6d8d7e599","tags":[]},{"id":"poem-82dad95cd29c8e3030f561fa","title":"题清远峡观音院二首 二","author":"卢肇","dynasty":"唐","verses":["风入古松添急雨，月临虚槛背残灯。","老猨啸狖还欺客，来撼窗前百尺藤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-f6135c93-7c18-44bb-9d64-bff0773f2f21","tags":[]},{"id":"poem-82e5f7b031055a31256a7bf8","title":"访罗孟弼竹园  其三","author":"张栻","dynasty":"宋","verses":["江梅独立荫颓墙，苔藓封枝色老苍。","手剪荆榛增叹息，眼中春意满三湘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-6eba2959-30d5-4ed1-afda-d655bbf0ba08","tags":[]},{"id":"poem-82ecdd764f8be8c41b140139","title":"和择之赋霜月","author":"张栻","dynasty":"宋","verses":["月华明洁好霜天，遥指层城几暮烟。","妙意此时谁与寄，美人湘水隔娟娟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-a886929e-8d67-417d-977b-209e578492dc","tags":[]},{"id":"poem-82ed9b1e39b4803cc4014afb","title":"题石窟寺","author":"宋昱","dynasty":"唐","verses":["梵宇开金地，香龛凿铁围。","影中群象动，空里众灵飞。","簷牖笼朱旭，房廊挹翠微。","瑞莲生佛步，瑶树挂天衣。","邀福功虽在，兴王代久非。","谁知云朔外，更覩化胡归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-700474d8-74f7-49ba-934c-bf5e02d2c469","tags":[]}];
